            {/* 世界书 token 预算占比 */}
            <div className="flex items-center justify-between mt-2 pt-2 border-t border-tavern-border-soft">
              <span className="flex items-center gap-0.5 text-xs text-tavern-text-muted">
                Token 预算占比
                <HintIcon
                  hint={
                    <>
                      <p>
