type SortKey = "updatedAt" | "createdAt" | "name"

function loadCardSize(): CardSize {
  try { return (localStorage.getItem("char-card-size") as CardSize) || "md" } catch { return "md" }
}

export function CharactersPage() {
  const navigate = useNavigate()
  const { characters, selectCharacter, deleteCharacter, importPng, importJson, importBatch, saveCharacter, createCharacter, importError, importNotice, pendingAvatarId, importProgress } = useCharacterStore()
  const [editing, setEditing] = useState(false)
  const [editCharacter, setEditCharacter] = useState<Character | null>(null)
  const [search, setSearch] = useState("")
  const [deleteId, setDeleteId] = useState<string | null>(null)
  const [viewMode, setViewMode] = useState<"grid" | "list">("grid")
  const [cardSize, setCardSize] = useState<CardSize>(loadCardSize)
  const [sortKey, setSortKey] = useState<SortKey>("updatedAt")
  const [detailCharacter, setDetailCharacter] = useState<Character | null>(null)
  const [batchResult, setBatchResult] = useState<{ total: number; successCount: number; failCount: number; fails: { name: string; error: string }[] } | null>(null)

  const deferredSearch = useDeferredValue(search)

  const filtered = useMemo(() => {
    let result = characters
    if (deferredSearch) {
      const q = deferredSearch.toLowerCase()
      result = result.filter((c) => {
        const nameMatch = c.name.toLowerCase().includes(q)
        const tagMatch = c.tags.some((t) => t.toLowerCase().includes(q))
        const descMatch = c.description?.toLowerCase().includes(q)
        const personalityMatch = c.personality?.toLowerCase().includes(q)
        const scenarioMatch = c.scenario?.toLowerCase().includes(q)
        return nameMatch || tagMatch || descMatch || personalityMatch || scenarioMatch
      })
    }
    return [...result].sort((a, b) => {
      if (a.pinned !== b.pinned) return a.pinned ? -1 : 1
      if (sortKey === "name") return a.name.localeCompare(b.name)
      return (b[sortKey] as number) - (a[sortKey] as number)
    })
  }, [characters, deferredSearch, sortKey])

  const handleCardSizeChange = (size: CardSize) => {
    setCardSize(size)
    try { localStorage.setItem("char-card-size", size) } catch { /* ignore */ }
  }

  const handleNew = () => {
    setEditCharacter(createCharacter())
    setEditing(true)
  }

  const handleEdit = useCallback((char: Character) => {
    setEditCharacter({ ...char })
    setEditing(true)
  }, [])

  const handleSave = async (char: Character) => {
    await saveCharacter(char)
    setEditing(false)
    setEditCharacter(null)
  }

  const handleStartChat = useCallback((char: Character) => {
    selectCharacter(char.id)
    navigate("/chat")
  }, [selectCharacter, navigate])

  const handleDetail = useCallback((char: Character) => {
    setDetailCharacter(char)
  }, [])

  const handleDeleteById = useCallback((id: string) => {
    setDeleteId(id)
  }, [])

  const handleDelete = async () => {
    if (deleteId) {
      await deleteCharacter(deleteId)
      setDeleteId(null)
    }
  }

  useEffect(() => {
    if (pendingAvatarId) {
      const char = characters.find(c => c.id === pendingAvatarId)
      if (char) {
        handleEdit(char)
        useCharacterStore.setState({ pendingAvatarId: null })
      }
    }
  }, [pendingAvatarId, characters])

  const handleBatchImport = async () => {
    const result = await importBatch()
    if (result) {
      const fails = (result.results || [])
        .filter(r => !r.success)
        .map(r => ({ name: r.name, error: r.error || "未知错误" }))
      setBatchResult({
        total: result.total || 0,
        successCount: result.successCount || 0,
        failCount: result.failCount || 0,
        fails,
      })
      setTimeout(() => setBatchResult(null), 8000)
    }
  }

  const gridClass = viewMode === "list" ? "" : {
    sm: "grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-6 xl:grid-cols-8 gap-2",
    md: "grid-cols-1 sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-4 xl:grid-cols-5 gap-3",
    lg: "grid-cols-1 sm:grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-3 gap-4",
  }[cardSize]

  return (
    <div className="flex-1 flex flex-col overflow-hidden">
      {importError && (
        <div className="flex items-center gap-2 px-4 py-2 bg-tavern-danger/10 border-b border-tavern-danger/30 text-tavern-danger text-sm animate-fade-in">
          <AlertCircle className="w-4 h-4 shrink-0" />
          <span className="flex-1">{importError}</span>
          <button onClick={() => useCharacterStore.setState({ importError: null })} className="p-0.5 hover:opacity-70">
            <X className="w-3.5 h-3.5" />
          </button>
        </div>
      )}

      {importNotice && (
        <div className="flex items-center gap-2 px-4 py-2 bg-emerald-500/10 border-b border-emerald-500/30 text-emerald-600 text-sm animate-fade-in">
          <Sparkles className="w-4 h-4 shrink-0" />
          <span className="flex-1">{importNotice}</span>
          <button onClick={() => useCharacterStore.setState({ importNotice: null })} className="p-0.5 hover:opacity-70">
            <X className="w-3.5 h-3.5" />
          </button>
        </div>
      )}

      {batchResult && (
        <div className={cn(
          "flex items-center gap-2 px-4 py-2 border-b text-sm animate-fade-in",
          batchResult.failCount > 0
            ? "bg-amber-500/10 border-amber-500/30 text-amber-600"
            : "bg-emerald-500/10 border-emerald-500/30 text-emerald-600"
        )}>
          {batchResult.failCount > 0 ? (
            <Info className="w-4 h-4 shrink-0" />
          ) : (
            <CheckCircle className="w-4 h-4 shrink-0" />
          )}
          <span className="flex-1">
            批量导入完成：成功 <strong>{batchResult.successCount}</strong> 个
            {batchResult.failCount > 0 && (
              <>，失败 <strong>{batchResult.failCount}</strong> 个
                {batchResult.fails.length > 0 && (
                  <span className="ml-1 text-tavern-text-muted">
                    （{batchResult.fails.map(f => f.name).join("、")}）
                  </span>
                )}
              </>
            )}
          </span>
          <button onClick={() => setBatchResult(null)} className="p-0.5 hover:opacity-70">
            <X className="w-3.5 h-3.5" />
          </button>
        </div>
      )}

      {importProgress && (
        <div className="px-4 py-3 border-b border-tavern-border-soft bg-tavern-bg-soft animate-fade-in">
          <div className="flex items-center justify-between mb-2">
            <div className="flex items-center gap-2 text-sm">
              {importProgress.status === "processing" ? (
                <Loader2 className="w-4 h-4 animate-spin text-tavern-accent" />
              ) : importProgress.status === "error" ? (
                <FileWarning className="w-4 h-4 text-tavern-danger" />
              ) : (
                <CheckCircle className="w-4 h-4 text-emerald-500" />
              )}
              <span className="text-tavern-text-soft">
                导入中 <strong>{importProgress.current}</strong> / {importProgress.total}
              </span>
            </div>
            <span className={cn(
              "text-xs truncate ml-4 max-w-[50%]",
              importProgress.status === "error" ? "text-tavern-danger" : "text-tavern-text-muted"
            )}>
              {importProgress.fileName}
            </span>
          </div>
          <div className="w-full h-2 rounded-full bg-tavern-bg-hover overflow-hidden">
            <div
              className="h-full rounded-full transition-all duration-300 ease-out"
              style={{
                width: `${Math.round((importProgress.current / importProgress.total) * 100)}%`,
                background: importProgress.status === "error"
                  ? "linear-gradient(90deg, #ef4444, #f87171)"
                  : "linear-gradient(90deg, #d4a574, #e8b88a)",
              }}
            />
          </div>
          <div className="text-xs text-tavern-text-muted text-right mt-0.5">
            {Math.round((importProgress.current / importProgress.total) * 100)}%
          </div>
        </div>
      )}

      <header className="flex items-center justify-between px-4 h-14 border-b border-tavern-border-soft bg-tavern-bg-soft shrink-0">
        <h1 className="font-display text-lg font-bold">角色管理</h1>
        <div className="flex items-center gap-2">
          <button onClick={handleNew} className="btn-primary">
            <Plus className="w-4 h-4" />
            新建角色
          </button>
          <button onClick={() => importPng()} className="btn-secondary" title="导入 PNG 角色卡">
            <FileUp className="w-4 h-4" />
            PNG
          </button>
          <button onClick={() => importJson()} className="btn-secondary" title="导入 JSON 角色卡">
            <Upload className="w-4 h-4" />
            JSON
          </button>
          <button onClick={handleBatchImport} className="btn-secondary" title="批量导入角色卡">
            <FileStack className="w-4 h-4" />
            批量导入
          </button>
        </div>
      </header>

      {characters.length > 0 && (
        <div className="px-4 py-3 border-b border-tavern-border-soft flex items-center gap-3 flex-wrap">
          <div className="relative max-w-xs flex-1 min-w-[160px]">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-tavern-text-muted" />
            <input
              type="text"
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              placeholder="搜索角色或标签..."
              className="input pl-9"
            />
          </div>
          <div className="flex items-center gap-1.5">
            <ArrowDownUp className="w-3.5 h-3.5 text-tavern-text-muted" />
            <select
              value={sortKey}
              onChange={(e) => setSortKey(e.target.value as SortKey)}
              className="text-xs bg-tavern-bg-hover border border-tavern-border rounded-md px-2 py-1.5 text-tavern-text-soft outline-none"
            >
              <option value="updatedAt">最近更新</option>
              <option value="createdAt">创建时间</option>
              <option value="name">名称</option>
            </select>
          </div>
          <div className="flex-1" />
          <div className="flex items-center gap-0.5 bg-tavern-bg-hover rounded-lg p-0.5">
            {(["sm", "md", "lg"] as CardSize[]).map((size) => (
              <button
                key={size}
                onClick={() => handleCardSizeChange(size)}
                className={cn(
                  "px-2.5 py-1 rounded text-xs font-medium transition-colors",
                  cardSize === size ? "bg-tavern-bg-card shadow-sm text-tavern-accent" : "text-tavern-text-muted hover:text-tavern-text"
                )}
                title={size === "sm" ? "小卡片" : size === "md" ? "中卡片" : "大卡片"}
              >
                {size === "sm" ? "小" : size === "md" ? "中" : "大"}
              </button>
            ))}
          </div>
          <div className="flex items-center gap-0.5 bg-tavern-bg-hover rounded-lg p-0.5">
            <button
              onClick={() => setViewMode("grid")}
              className={cn("p-1.5 rounded transition-colors", viewMode === "grid" ? "bg-tavern-bg-card shadow-sm text-tavern-accent" : "text-tavern-text-muted hover:text-tavern-text")}
              title="网格视图"
            >
              <Grid3X3 className="w-4 h-4" />
            </button>
            <button
              onClick={() => setViewMode("list")}
              className={cn("p-1.5 rounded transition-colors", viewMode === "list" ? "bg-tavern-bg-card shadow-sm text-tavern-accent" : "text-tavern-text-muted hover:text-tavern-text")}
              title="列表视图"
            >
              <List className="w-4 h-4" />
            </button>
          </div>
        </div>
      )}

      <div className="flex-1 overflow-hidden p-4">
        {characters.length === 0 ? (
          <EmptyState
            className="h-full"
            icon={<Users className="w-8 h-8" />}
            title="还没有角色"
            description="创建你的第一个角色，或从 SillyTavern 导入角色卡"
            action={
              <div className="flex gap-2">
                <button className="btn-primary" onClick={handleNew}>
                  <Plus className="w-4 h-4" />
                  新建角色
                </button>
                <button className="btn-secondary" onClick={() => importPng()}>
                  <FileUp className="w-4 h-4" />
                  导入角色卡
                </button>
              </div>
            }
          />
        ) : filtered.length === 0 ? (
          <EmptyState
            className="h-full"
            icon={<Search className="w-8 h-8" />}
            title="未找到匹配的角色"
            description={`没有包含 "${search}" 的角色`}
          />
        ) : viewMode === "list" ? (
          <Virtuoso
            data={filtered}
            itemContent={(index, char) => (
              <CharacterCard
                key={char.id}
                character={char}
                viewMode="list"
                cardSize={cardSize}
                onDetail={handleDetail}
                onEdit={handleEdit}
                onDelete={handleDeleteById}
                onChat={handleStartChat}
              />
            )}
            className="h-full"
            components={{
              List: ({ children }) => <div className="flex flex-col gap-3 max-w-3xl mx-auto pb-4">{children}</div>,
            }}
          />
        ) : (
          <VirtuosoGrid
            data={filtered}
            itemContent={(index, char) => (
              <CharacterCard
                key={char.id}
                character={char}
                cardSize={cardSize}
                onDetail={handleDetail}
                onEdit={handleEdit}
                onDelete={handleDeleteById}
                onChat={handleStartChat}
              />
            )}
            listClassName={cn("grid", gridClass)}
            className="h-full"
          />
        )}
      </div>

      {editing && editCharacter && (
        <CharacterEditor
          character={editCharacter}
          onSave={handleSave}
          onClose={() => { setEditing(false); setEditCharacter(null) }}
        />
      )}

      {detailCharacter && (
        <CharacterDetail
          character={detailCharacter}
          onClose={() => setDetailCharacter(null)}
          onEdit={() => {
            setDetailCharacter(null)
            handleEdit(detailCharacter)
          }}
          onChat={() => handleStartChat(detailCharacter)}
        />
      )}

      <ConfirmDialog
        open={!!deleteId}
        onClose={() => setDeleteId(null)}
        onConfirm={handleDelete}
        title="删除角色"
        message="确定要删除这个角色吗？相关的对话记录也将被删除。此操作不可撤销。"
        confirmText="删除"
        danger
      />
    </div>
  )
}

import { useEffect, useRef, useState, useMemo } from 'react'
import { useNavigate } from 'react-router-dom'
import { Virtuoso, type VirtuosoHandle } from 'react-virtuoso'
import { useChatStore } from '../store/useChatStore'
import { useCharacterStore } from '../store/useCharacterStore'
import { charAssetUrl } from '../utils/asset'
import { isLocalProvider } from '../utils/defaults'
import { useSettingsStore } from '../store/useSettingsStore'
import { usePersonaStore } from '../store/usePersonaStore'
import { MessageBubble } from '../components/chat/MessageBubble'
import { ChatInput } from '../components/chat/ChatInput'
import { EmptyState } from '../components/common/EmptyState'
import { ConfirmDialog } from '../components/common/ConfirmDialog'
import { ChatHeader } from '../components/chat/ChatHeader'
import { Modal } from '../components/common/Modal'
import { QuickSettingsPanel } from '../components/chat/QuickSettingsPanel'
import { BackgroundPanel, PRESET_GRADIENTS } from '../components/chat/BackgroundPanel'
import { ContextViewer } from '../components/chat/ContextViewer'
import { StatusBar } from '../components/chat/StatusBar'
import { cn } from '../lib/utils'
import { logError } from '../lib/logger'
import { countChars } from '../utils/charCounter'
import { replaceVariables, getDisplayName } from '../utils/variables'
import { getEffectiveLorebookIds } from '../utils/lorebook'
import { downloadFile } from '../utils/download'
import { nanoid } from 'nanoid'
import type { Message } from '../../shared/types'
import {
  MessageSquare,
  Settings as SettingsIcon,
  Users,
  Sparkles,
  X,
  AlertTriangle,
} from 'lucide-react'

/** 长对话摘要引导提示的消息数阈值 */
const MEMORY_HINT_THRESHOLD = 40

export function ChatPage() {
  const navigate = useNavigate()
  const { messages, loadMessages, isStreaming, clearChat, clearMessages, currentSessionId, loadSessions, setActiveLorebooks, activeLorebookIds, sessions } = useChatStore()
  const { currentCharacter } = useCharacterStore()
  const { settings, loaded, getActiveProfile } = useSettingsStore()
  const { loadPersonas } = usePersonaStore()
  const [showClearConfirm, setShowClearConfirm] = useState(false)
  const [showQuickSettings, setShowQuickSettings] = useState(false)
  const [showBgPanel, setShowBgPanel] = useState(false)
  const [showContextViewer, setShowContextViewer] = useState(false)
  const [greetingPickerOpen, setGreetingPickerOpen] = useState(false)
  const [selectedGreeting, setSelectedGreeting] = useState('')
  // 世界书绑定确认弹窗
  const [showLorebookConfirm, setShowLorebookConfirm] = useState(false)
  const [pendingLorebookIds, setPendingLorebookIds] = useState<string[]>([])
  // 长对话摘要引导提示：记录已关闭提示的会话 ID
  const [memoryHintDismissed, setMemoryHintDismissed] = useState<string | null>(null)
  /** 引用回复：被引用的目标消息（P1-5） */
  const [replyToMessage, setReplyToMessage] = useState<Message | null>(null)
  const pendingSessionCallbackRef = useRef<(() => void) | null>(null)
  const messagesEndRef = useRef<HTMLDivElement>(null)
  const virtuosoRef = useRef<VirtuosoHandle>(null)
  // 背景图片拖拽状态
  const [isDraggingBg, setIsDraggingBg] = useState(false)
  const bgImgRef = useRef<HTMLImageElement>(null)
  const bgDragRef = useRef({ startX: 0, startY: 0, startPosX: 0, startPosY: 0 })

  const activeProfile = getActiveProfile()
  const isConnected = activeProfile !== null && (isLocalProvider(activeProfile.provider) || !!activeProfile.apiKey)

  // 长对话且未开启长记忆时，引导开启自动摘要（节省 token + 保持主题连贯）
  const currentChatSession = sessions.find(s => s.id === currentSessionId)
  const showMemoryHint = !!currentCharacter && !!currentSessionId
    && messages.length >= MEMORY_HINT_THRESHOLD
    && !!currentChatSession && !currentChatSession.memoryEnabled
    && memoryHintDismissed !== currentSessionId

  const handleEnableAutoMemory = async () => {
    if (!currentCharacter || !currentSessionId) return
    setMemoryHintDismissed(currentSessionId)
    try {
      const store = useChatStore.getState()
      await store.toggleMemory(currentCharacter.id, currentSessionId, true)
      await store.setMemoryMode(currentCharacter.id, currentSessionId, 'auto')
    } catch (e) {
      logError('ChatPage:enableAutoMemory', e)
    }
  }

  // 上下文上限预警（P1-3）：读取最近一次 buildContext 的用量
  const lastContextUsage = useChatStore((s) => s.lastContextUsage)
  const contextUsage = lastContextUsage && lastContextUsage.max > 0
    ? {
        used: lastContextUsage.used,
        max: lastContextUsage.max,
        ratio: lastContextUsage.used / lastContextUsage.max,
        pct: Math.min(999, Math.round((lastContextUsage.used / lastContextUsage.max) * 100)),
      }
    : null

  const handleSummarizeFromWarning = async () => {
    if (!currentCharacter) return
    try {
      const store = useChatStore.getState()
      const result = await store.triggerMemorySummary(currentCharacter)
      if (!result) {
        // 记忆未启用时提示引导
        if (currentSessionId) await store.toggleMemory(currentCharacter.id, currentSessionId, true)
      }
    } catch (e) {
      logError('ChatPage:summarizeFromWarning', e)
    }
  }

  // 加载消息（切换角色时）
  useEffect(() => {
    if (currentCharacter) {
      // 切换角色时取消任何进行中的流式请求
      if (useChatStore.getState().isStreaming) {
        useChatStore.getState().stopStreaming()
      }
      loadSessions(currentCharacter.id)
        .then(() => loadMessages(currentCharacter))
        .then(() => {
          // 检测是否有备选开场白
          const state = useChatStore.getState()
          const hasAltGreetings = currentCharacter.alternateGreetings && currentCharacter.alternateGreetings.length > 0
          // 双重检查：messages 为空 且 当前 session 的 messageCount 也为 0，才弹出选择器
          const currentSession = state.sessions.find(s => s.id === state.currentSessionId)
          const hasExistingMessages = currentSession && currentSession.messageCount > 0
          if (hasAltGreetings && state.messages.length === 0 && !hasExistingMessages) {
            setSelectedGreeting(currentCharacter.translatedContent?.firstMessage ?? currentCharacter.firstMessage)
            setGreetingPickerOpen(true)
          }
        })
        .catch((err) => {
          logError('ChatPage:loadSession', err)
        })
      // B-05 修复：切换角色时替换（非合并）预设为新角色的绑定
      const chatStore = useChatStore.getState()
      // 预设：有绑定则激活，无绑定则重置为 null
      const targetPreset = currentCharacter.boundPresetId ?? null
      if (targetPreset !== chatStore.activePresetId) {
        chatStore.setActivePreset(targetPreset)
      }
      // 世界书：由 loadMessages → syncLorebooksFromCurrentSession 处理，不在此处手动同步
    } else {
      clearMessages()
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [currentCharacter?.id])

  // 加载 persona 列表
  useEffect(() => { loadPersonas() }, [])

  // 流式输出时自动滚动到底部：每次内容更新都锁定最后一行
  useEffect(() => {
    if (!isStreaming || !settings.autoScroll) return
    requestAnimationFrame(() => {
      virtuosoRef.current?.scrollToIndex({ index: messages.length - 1, align: 'end', behavior: 'auto' })
    })
  }, [messages, isStreaming, settings.autoScroll])

  // 全局键盘快捷键事件监听
  useEffect(() => {
    const handleExportChat = async () => {
      await handleExport()
    }
    const handleCopyLastAi = async () => {
      const lastAssistant = [...messages].reverse().find(m => m.role === 'assistant')
      if (lastAssistant) {
        await navigator.clipboard.writeText(lastAssistant.content)
      }
    }
    window.addEventListener('shortcut:export-chat', handleExportChat)
    window.addEventListener('shortcut:copy-last-ai', handleCopyLastAi)
    return () => {
      window.removeEventListener('shortcut:export-chat', handleExportChat)
      window.removeEventListener('shortcut:copy-last-ai', handleCopyLastAi)
    }
  }, [messages, currentCharacter, currentSessionId])

  // 新建会话统一入口（从 ChatHeader 触发）：检查绑定世界书 → 弹窗确认 → 创建会话
  const handleCreateSession = () => {
    checkBoundLorebooks(async () => {
      if (!currentCharacter) return
      const store = useChatStore.getState()
      await store.createSession(currentCharacter.id)
      // 如果有开场白，弹出选择器
      const hasGreetings = currentCharacter.firstMessage || (currentCharacter.alternateGreetings && currentCharacter.alternateGreetings.length > 0)
      if (hasGreetings) {
        setGreetingPickerOpen(true)
      }
    })
  }

  // 字符统计：useMemo 避免流式时每个 chunk 都重算
  const totalChars = useMemo(() => {
    return messages.reduce((sum, m) => sum + countChars(m.content).total, 0)
  }, [messages])

  // 检查角色是否有绑定的世界书，如果有则弹窗确认
  const checkBoundLorebooks = (callback: () => void) => {
    if (!currentCharacter) {
      callback()
      return
    }
    const boundIds = getEffectiveLorebookIds(currentCharacter)
    if (boundIds.length === 0) {
      callback()
      return
    }
    // 检查是否已经激活了这些世界书
    const currentSet = new Set(activeLorebookIds)
    const allActive = boundIds.every(id => currentSet.has(id))
    if (allActive) {
      callback()
      return
    }
    // 弹窗确认，存储回调
    pendingSessionCallbackRef.current = callback
    setPendingLorebookIds(boundIds)
    setShowLorebookConfirm(true)
  }

  // 确认使用绑定的世界书
  const handleLorebookConfirm = async (useLorebooks: boolean) => {
    setShowLorebookConfirm(false)
    if (useLorebooks && pendingLorebookIds.length > 0) {
      setActiveLorebooks(pendingLorebookIds, currentCharacter?.id)
    }
    setPendingLorebookIds([])
    // 执行待处理的会话创建回调
    if (pendingSessionCallbackRef.current) {
      pendingSessionCallbackRef.current()
      pendingSessionCallbackRef.current = null
    }
  }

  // 导出对话
  const handleExport = async () => {
    if (!currentCharacter || !currentSessionId) return
    const content = await window.api.chat.exportChat(currentCharacter.id, currentSessionId, 'md')
    downloadFile(content, `${currentCharacter.name}-对话.md`)
  }

  // 使用选中开场白开始对话
  const handleStartWithGreeting = async () => {
    if (!currentCharacter || !selectedGreeting) return
    setGreetingPickerOpen(false)

    // 检查绑定的世界书
    checkBoundLorebooks(async () => {
      // 确保存在会话：没有已有会话时自动创建
      let sid = currentSessionId
      if (!sid) {
        const session = await window.api.chat.createSession(currentCharacter.id)
        const sessions = await window.api.chat.listSessions(currentCharacter.id)
        useChatStore.setState({ sessions, currentSessionId: session.id })
        // 持久化当前会话 ID，确保重启后能恢复
        useSettingsStore.getState().updateSettings({ activeSessionId: session.id })
        // 同步新会话绑定的身份（后端继承默认身份）到 settings，使发送消息立即生效
        const persona = session.personaId ? usePersonaStore.getState().getPersona(session.personaId) : undefined
        if (persona) {
          useSettingsStore.getState().updateSettings({
            activePersonaId: persona.id,
            userName: persona.name,
            userDescription: persona.description,
            userPersona: persona.persona,
          })
        }
        sid = session.id
      }

    const settings = useSettingsStore.getState().settings
    const processed = replaceVariables(selectedGreeting, settings.userName, currentCharacter.name)
    const firstMsg: Message = {
      id: nanoid(),
      sessionId: sid,
      characterId: currentCharacter.id,
      role: 'assistant',
      content: processed,
      images: [],
      isEditing: false,
      timestamp: Date.now(),
    }
    await window.api.chat.saveMessage(firstMsg)
    // 刷新 sessions 以更新 messageCount，确保下次加载时不重复弹出选择器
    const updatedSessions = await window.api.chat.listSessions(currentCharacter.id)
    useChatStore.setState({ messages: [firstMsg], sessions: updatedSessions, currentSessionId: sid })
    })
  }

  // 背景图片拖拽
  const handleBgMouseDown = (e: React.MouseEvent) => {
    const params = currentCharacter?.chatBackgroundParams
    if (!params) return
    bgDragRef.current = {
      startX: e.clientX,
      startY: e.clientY,
      startPosX: params.posX ?? 50,
      startPosY: params.posY ?? 50,
    }
    setIsDraggingBg(true)
    e.preventDefault()
  }

  useEffect(() => {
    if (!isDraggingBg) return

    const handleMouseMove = (e: MouseEvent) => {
      const { startX, startY, startPosX, startPosY } = bgDragRef.current
      const scale = 0.4 // 1px 鼠标移动 ≈ 0.4% 位置变化
      const newPosX = Math.max(0, Math.min(100, startPosX + (e.clientX - startX) * scale))
      const newPosY = Math.max(0, Math.min(100, startPosY + (e.clientY - startY) * scale))
      if (bgImgRef.current) {
        bgImgRef.current.style.objectPosition = `${newPosX}% ${newPosY}%`
      }
    }

    const handleMouseUp = async (e: MouseEvent) => {
      const { startX, startY, startPosX, startPosY } = bgDragRef.current
      const scale = 0.4
      const newPosX = Math.max(0, Math.min(100, startPosX + (e.clientX - startX) * scale))
      const newPosY = Math.max(0, Math.min(100, startPosY + (e.clientY - startY) * scale))
      setIsDraggingBg(false)

      const store = useCharacterStore.getState()
      if (store.currentCharacter) {
        const updated = {
          ...store.currentCharacter,
          chatBackgroundParams: {
            ...store.currentCharacter.chatBackgroundParams!,
            posX: Math.round(newPosX),
            posY: Math.round(newPosY),
          },
        }
        await store.saveCharacter(updated)
      }
    }

    window.addEventListener('mousemove', handleMouseMove)
    window.addEventListener('mouseup', handleMouseUp)
    return () => {
      window.removeEventListener('mousemove', handleMouseMove)
      window.removeEventListener('mouseup', handleMouseUp)
    }
  }, [isDraggingBg])

  // 聊天背景：优先使用 chatBackgroundParams.useCover（角色封面）或手动设置的背景图/渐变
  const effectiveBg = useMemo(() => {
    const params = currentCharacter?.chatBackgroundParams
    const coverSrc = currentCharacter?.cover || currentCharacter?.avatar
    if (params?.useCover && coverSrc) {
      return {
        src: coverSrc,
        type: 'image' as const,
        opacity: params.opacity ?? 12,
        blur: params.blur ?? 0,
        posX: params.posX ?? 50,
        posY: params.posY ?? 50,
        scale: params.scale ?? 100,
      }
    }
    if (currentCharacter?.chatBackground) {
      return {
        src: currentCharacter.chatBackground,
        type: params?.type ?? 'image',
        opacity: params?.opacity ?? 12,
        blur: params?.blur ?? 2,
        posX: params?.posX ?? 50,
        posY: params?.posY ?? 50,
        scale: params?.scale ?? 100,
        gradient: params?.gradient,
      }
    }
    return null
  }, [currentCharacter?.id, currentCharacter?.updatedAt, currentCharacter?.chatBackground, currentCharacter?.chatBackgroundParams])

  // 首次使用引导
  if (loaded && !isConnected) {
    return (
      <div className="flex-1 flex items-center justify-center p-8">
        <div className="max-w-md text-center">
          <div className="w-20 h-20 mx-auto rounded-2xl bg-tavern-accent-soft flex items-center justify-center mb-6">
            <MessageSquare className="w-10 h-10 text-tavern-accent" />
          </div>
          <h2 className="text-xl font-display font-bold mb-2">欢迎使用轻语</h2>
          <p className="text-tavern-text-soft mb-6">
            开始你的 AI 角色扮演之旅。只需 3 步即可开启对话：
          </p>
          <div className="text-left space-y-3 mb-6">
            <div className="flex gap-3 items-start p-3 rounded-lg bg-tavern-bg-card">
              <span className="w-6 h-6 rounded-full bg-tavern-accent text-tavern-bg flex items-center justify-center text-sm font-bold shrink-0">1</span>
              <div>
                <div className="font-medium text-tavern-text">配置 AI 连接</div>
                <div className="text-sm text-tavern-text-muted">选择 AI 服务商并填入 API 密钥</div>
              </div>
            </div>
            <div className="flex gap-3 items-start p-3 rounded-lg bg-tavern-bg-card">
              <span className="w-6 h-6 rounded-full bg-tavern-accent text-tavern-bg flex items-center justify-center text-sm font-bold shrink-0">2</span>
              <div>
                <div className="font-medium text-tavern-text">选择或创建角色</div>
                <div className="text-sm text-tavern-text-muted">从角色库选择，或创建你的专属角色</div>
              </div>
            </div>
            <div className="flex gap-3 items-start p-3 rounded-lg bg-tavern-bg-card">
              <span className="w-6 h-6 rounded-full bg-tavern-accent text-tavern-bg flex items-center justify-center text-sm font-bold shrink-0">3</span>
              <div>
                <div className="font-medium text-tavern-text">开始对话</div>
                <div className="text-sm text-tavern-text-muted">输入消息，享受沉浸式角色扮演</div>
              </div>
            </div>
          </div>
          <button className="btn-primary w-full" onClick={() => navigate('/settings')}>
            <SettingsIcon className="w-4 h-4" />
            开始配置
          </button>
        </div>
      </div>
    )
  }


  if (!currentCharacter) {
    return (
      <div className="flex-1 flex items-center justify-center">
        <EmptyState
          icon={<Users className="w-8 h-8" />}
          title="选择一个角色开始对话"
          description="从左侧角色库中选择，或创建新角色"
          action={
            <button className="btn-primary" onClick={() => navigate('/characters')}>
              <Users className="w-4 h-4" />
              前往角色管理
            </button>
          }
        />
      </div>
    )
  }

  return (
    <div className="flex-1 flex flex-col overflow-hidden relative">
      {/* 背景图层 */}
      {effectiveBg && (
        <div
          className={cn(
            'absolute inset-0 z-0 select-none overflow-hidden',
            effectiveBg.type === 'image' ? 'pointer-events-auto' : 'pointer-events-none'
          )}
        >
          {effectiveBg.type === 'gradient' && effectiveBg.gradient ? (
            <div
              className="w-full h-full scale-105"
              style={{
                background: PRESET_GRADIENTS.find(g => g.key === effectiveBg.gradient)?.css,
                opacity: effectiveBg.opacity / 100,
                filter: `blur(${effectiveBg.blur}px)`,
              }}
            />
          ) : (
            <img
              ref={bgImgRef}
              src={effectiveBg.src}
              className="w-full h-full object-cover"
              style={{
                opacity: effectiveBg.opacity / 100,
                filter: effectiveBg.blur > 0 ? `blur(${effectiveBg.blur}px)` : undefined,
                objectPosition: `${effectiveBg.posX}% ${effectiveBg.posY}%`,
                transform: `scale(${effectiveBg.scale / 100})`,
                imageRendering: 'auto',
                cursor: isDraggingBg ? 'grabbing' : 'grab',
              }}
              onMouseDown={handleBgMouseDown}
              alt=""
              draggable={false}
            />
          )}
        </div>
      )}

      {/* 顶栏 */}
      <ChatHeader
        currentCharacter={currentCharacter}
        messages={messages}
        isStreaming={isStreaming}
        totalChars={totalChars}
        showQuickSettings={showQuickSettings}
        showBgPanel={showBgPanel}
        onExport={handleExport}
        onClearConfirm={() => setShowClearConfirm(true)}
        onShowContextViewer={() => setShowContextViewer(true)}
        onShowQuickSettings={() => setShowQuickSettings(!showQuickSettings)}
        onShowBgPanel={() => setShowBgPanel(!showBgPanel)}
        onShowGreetingPicker={() => {
          setSelectedGreeting(currentCharacter.translatedContent?.firstMessage ?? currentCharacter.firstMessage)
          setGreetingPickerOpen(true)
        }}
        onCreateSession={handleCreateSession}
      />

      {/* 状态栏 — 有消息或有激活世界书时显示 */}
      {currentCharacter && (
        <div className="relative z-10"><StatusBar character={currentCharacter} messages={messages} /></div>
      )}

      {/* 长对话摘要引导提示条 */}
      {showMemoryHint && (
        <div className="relative z-10 flex items-center gap-2 px-4 py-1.5 text-xs bg-tavern-accent-soft border-b border-tavern-border-soft animate-fade-in">
          <Sparkles className="w-3.5 h-3.5 text-tavern-accent shrink-0" />
          <span className="flex-1 text-tavern-text-soft truncate">对话较长，开启自动摘要可节省 token 并保持主题连贯</span>
          <button
            onClick={handleEnableAutoMemory}
            className="px-2 py-0.5 rounded font-medium text-tavern-accent hover:bg-tavern-accent/10 transition-colors shrink-0"
          >
            开启
          </button>
          <button
            onClick={() => setMemoryHintDismissed(currentSessionId)}
            className="text-tavern-text-muted hover:text-tavern-text transition-colors shrink-0"
            title="本次会话不再提示"
          >
            <X className="w-3.5 h-3.5" />
          </button>
        </div>
      )}

      {/* 上下文上限预警（P1-3）：用量 ≥85% 显示 */}
      {contextUsage && contextUsage.ratio >= 0.85 && (
        <div className={cn(
          'relative z-10 flex items-center gap-2 px-4 py-1.5 text-xs border-b animate-fade-in',
          contextUsage.ratio >= 1 ? 'bg-tavern-danger/10 border-tavern-danger/20' : 'bg-tavern-warning/10 border-tavern-warning/20'
        )}>
          <AlertTriangle className={cn('w-3.5 h-3.5 shrink-0', contextUsage.ratio >= 1 ? 'text-tavern-danger' : 'text-tavern-warning')} />
          <span className="flex-1 text-tavern-text-soft truncate">
            上下文已使用 {contextUsage.pct}%（{contextUsage.used}/{contextUsage.max} token）
            {contextUsage.ratio >= 1 ? '，将裁剪早期历史' : '，接近上限将裁剪早期历史'}
          </span>
          <button
            onClick={handleSummarizeFromWarning}
            className="px-2 py-0.5 rounded font-medium text-tavern-accent hover:bg-tavern-accent/10 transition-colors shrink-0"
          >
            立即总结
          </button>
          <button
            onClick={() => useChatStore.getState().clearChat(currentCharacter!.id)}
            className="px-2 py-0.5 rounded font-medium text-tavern-text-muted hover:text-tavern-danger hover:bg-tavern-danger/10 transition-colors shrink-0"
          >
            清理历史
          </button>
        </div>
      )}

      {/* 消息列表 - 使用 Virtuoso 虚拟滚动 */}
      <div
        className={cn(
          'flex-1 overflow-hidden relative z-0',
          `bubble-${settings.bubbleStyle}`
        )}
      >
        {messages.length === 0 ? (
          <EmptyState
            className="h-full"
            icon={<MessageSquare className="w-8 h-8" />}
            title="开始新的对话"
            description={`与 ${getDisplayName(currentCharacter)} 开始你的故事`}
          />
        ) : (
          <Virtuoso
            key={currentSessionId || 'empty'}
            ref={virtuosoRef}
            data={messages}
            className="h-full"
            initialTopMostItemIndex={999999}
            followOutput={settings.autoScroll ? 'smooth' : false}
            itemContent={(index, msg) => {
              const replied = msg.replyToId ? messages.find((m) => m.id === msg.replyToId) ?? null : null
              return (
                <MessageBubble
                  key={msg.id}
                  message={msg}
                  character={currentCharacter}
                  isLast={index === messages.length - 1}
                  repliedMessage={replied}
                  onReply={() => setReplyToMessage(msg)}
                />
              )
            }}
            components={{
              Footer: () => <div ref={messagesEndRef} className="h-4" />,
            }}
          />
        )}
      </div>

      {/* 输入区 */}
      <div className="relative z-10">
        <ChatInput
          character={currentCharacter}
          replyTo={replyToMessage}
          onCancelReply={() => setReplyToMessage(null)}
        />
      </div>

      {/* 清空确认 */}
      <ConfirmDialog
        open={showClearConfirm}
        onClose={() => setShowClearConfirm(false)}
        onConfirm={async () => {
          await clearChat(currentCharacter.id)
          // 清空后自动插入开场白或弹出选择器
          const hasAltGreetings = currentCharacter.alternateGreetings && currentCharacter.alternateGreetings.length > 0
          if (hasAltGreetings) {
            setSelectedGreeting(currentCharacter.translatedContent?.firstMessage ?? currentCharacter.firstMessage)
            setGreetingPickerOpen(true)
          } else if (currentCharacter.firstMessage) {
            const settings = useSettingsStore.getState().settings
            const processed = replaceVariables(currentCharacter.firstMessage, settings.userName, currentCharacter.name)
            const firstMsg: Message = {
              id: nanoid(),
              sessionId: currentSessionId!,
              characterId: currentCharacter.id,
              role: 'assistant',
              content: processed,
              images: [],
              isEditing: false,
              timestamp: Date.now(),
            }
            await window.api.chat.saveMessage(firstMsg)
            useChatStore.setState(s => ({ messages: [...s.messages, firstMsg] }))
          }
        }}
        title="清空对话"
        message={`确定要清空与 ${getDisplayName(currentCharacter)} 的所有对话记录吗？此操作不可撤销。`}
        confirmText="清空"
        danger
      />

      {/* 世界书绑定确认 */}
      <ConfirmDialog
        open={showLorebookConfirm}
        onClose={() => {
          setShowLorebookConfirm(false)
          setPendingLorebookIds([])
        }}
        onConfirm={() => handleLorebookConfirm(true)}
        cancelText="不使用"
        title="使用绑定的世界书"
        message={`当前角色绑定了 ${pendingLorebookIds.length} 个世界书，是否在本次对话中使用？`}
        confirmText="使用"
      />

      {/* 快捷设置面板 */}
      <QuickSettingsPanel open={showQuickSettings} onClose={() => setShowQuickSettings(false)} />
      <BackgroundPanel open={showBgPanel} onClose={() => setShowBgPanel(false)} />

      {/* 开场白选择面板 */}
      <Modal
        open={greetingPickerOpen && !!currentCharacter}
        onClose={() => { setGreetingPickerOpen(false); setSelectedGreeting('') }}
        width="custom"
        widthClassName="w-[560px]"
        headerClassName="px-5 py-4 bg-tavern-bg-soft"
        header={
          <div className="flex items-center gap-3 flex-1 min-w-0">
            <div className="w-12 h-12 rounded-lg overflow-hidden bg-tavern-bg-hover shrink-0">
              {currentCharacter ? (
                <img
                  src={currentCharacter ? charAssetUrl(currentCharacter.id, 'cover', currentCharacter.updatedAt) : ''}
                  alt=""
                  className="w-full h-full object-cover"
                  onError={(e) => { (e.target as HTMLImageElement).style.display = 'none' }}
                />
              ) : (
                <div className="w-full h-full flex items-center justify-center text-tavern-text-muted text-lg font-display">
                  {currentCharacter?.translatedContent?.name?.[0] ?? currentCharacter?.name[0]}
                </div>
              )}
            </div>
            <div className="flex-1 min-w-0">
              <h3 className="font-display font-bold text-lg truncate">{getDisplayName(currentCharacter)}</h3>
              <p className="text-xs text-tavern-text-muted">选择一个开场白开始对话</p>
            </div>
          </div>
        }
        footer={
          <>
            <span className={cn(
              'text-xs mr-auto',
              selectedGreeting ? 'text-tavern-accent' : 'text-tavern-text-muted'
            )}>
              {selectedGreeting ? '✓ 已选择开场白' : '请选择一条开场白，或跳过直接开始'}
            </span>
            <button className="btn-secondary" onClick={() => { setGreetingPickerOpen(false); setSelectedGreeting('') }}>
              跳过
            </button>
            <button className="btn-primary" onClick={handleStartWithGreeting} disabled={!selectedGreeting}>
              开始对话
            </button>
          </>
        }
      >
        {currentCharacter && (
          <div className="space-y-2">
            {[currentCharacter.translatedContent?.firstMessage ?? currentCharacter.firstMessage, ...(currentCharacter.alternateGreetings || [])]
              .filter(Boolean)
              .map((greeting, i) => (
                <div
                  key={i}
                  className={cn(
                    'p-3 rounded-lg border cursor-pointer transition-all text-sm',
                    selectedGreeting === greeting
                      ? 'border-tavern-accent bg-tavern-accent-soft shadow-sm'
                      : 'border-tavern-border hover:bg-tavern-bg-hover hover:border-tavern-border-soft'
                  )}
                  onClick={() => setSelectedGreeting(greeting)}
                >
                  <div className="flex gap-2.5">
                    <span className={cn(
                      'shrink-0 w-5 h-5 rounded-full flex items-center justify-center text-xs font-bold mt-0.5',
                      selectedGreeting === greeting
                        ? 'bg-tavern-accent text-tavern-bg'
                        : 'bg-tavern-bg-hover text-tavern-text-muted'
                    )}>
                      {i + 1}
                    </span>
                    <div className="flex-1 line-clamp-4 whitespace-pre-wrap text-tavern-text-soft">
                      {replaceVariables(greeting, settings.userName, currentCharacter.translatedContent?.name ?? currentCharacter.name)}
                    </div>
                  </div>
                </div>
              ))}
          </div>
        )}
      </Modal>

      {/* 上下文查看器 */}
      <ContextViewer
        open={showContextViewer}
        onClose={() => setShowContextViewer(false)}
        character={currentCharacter}
        preset={null}
      />
    </div>
  )
}

import { useEffect, useState, useRef } from 'react'
import type React from 'react'
import { nanoid } from 'nanoid'
import { Virtuoso, type VirtuosoHandle } from 'react-virtuoso'
import { useCharacterStore } from '../store/useCharacterStore'
import { useGroupChatStore } from '../store/useGroupChatStore'
import { GroupChatMessage } from '../components/chat/GroupChatMessage'
import { GroupChatInput } from '../components/chat/GroupChatInput'
import { GroupMemberBar } from '../components/chat/GroupMemberBar'
import { EmptyState } from '../components/common/EmptyState'
import { ConfirmDialog } from '../components/common/ConfirmDialog'
import { Modal } from '../components/common/Modal'
import { GreetingPickerModal } from './group/GreetingPickerModal'
import { NewGroupModal } from './group/NewGroupModal'
import { SessionSwitcher } from '../components/common/SessionSwitcher'
import { GroupChatSettingsPanel } from '../components/chat/GroupChatSettingsPanel'
import { MemoryPanel } from '../components/chat/MemoryPanel'
import { cn } from '../lib/utils'
import { downloadFile } from '../utils/download'
import type { GroupChat, GroupMessage, Lorebook, Preset } from '../../shared/types'
import {
  Plus,
  Trash2,
  Users,
  MessageSquare,
  Settings2,
  Edit2,
  Check,
  Eye,
  PanelLeftClose,
  PanelLeftOpen,
} from 'lucide-react'

export function GroupChatPage() {
  const { characters } = useCharacterStore()
  const {
    groupChats, currentGroup, sessions, currentSessionId,
    messages,
    isStreaming,
    loadGroups, selectGroup, saveGroup, deleteGroup,
    createSession, switchSession, deleteSession, renameSession,
    clearChat, deleteMessage, editMessage, regenerateMessage, translateMessage,
    sendPollingRound,
    toggleMemory, setMemoryMode, triggerMemorySummary,
  } = useGroupChatStore()

  const [selectedId, setSelectedId] = useState<string | null>(null)
  const [showDeleteConfirm, setShowDeleteConfirm] = useState(false)
  const [deletingId, setDeletingId] = useState<string | null>(null)
  const [editingName, setEditingName] = useState(false)
  const [nameDraft, setNameDraft] = useState('')
  const [showSettings, setShowSettings] = useState(false)
  const [lorebooks, setLorebooks] = useState<Lorebook[]>([])
  const [presets, setPresets] = useState<Preset[]>([])
  const virtuosoRef = useRef<VirtuosoHandle>(null)
  const [showContextViewer, setShowContextViewer] = useState(false)
  const [contextContent, setContextContent] = useState<{ role: string; content: string }[]>([])
  const [showGreetingPicker, setShowGreetingPicker] = useState(false)
  const [showClearConfirm, setShowClearConfirm] = useState(false)
  const [replyToMessage, setReplyToMessage] = useState<GroupMessage | null>(null)
  const [showMemoryPanel, setShowMemoryPanel] = useState(false)
  const [memoryInterval, setMemoryInterval] = useState(10)
  const [showCreateModal, setShowCreateModal] = useState(false)
  const [selectedMemberIds, setSelectedMemberIds] = useState<string[]>([])
  const [memberSearch, setMemberSearch] = useState('')
  const [sidebarCollapsed, setSidebarCollapsed] = useState(false)

  // 初始加载
  useEffect(() => {
    loadGroups()
  }, [])

  // 如果当前群聊有成员且无消息，自动弹出开场白选择器
  useEffect(() => {
    if (currentGroup && messages.length === 0 && !isStreaming && currentGroup.memberIds.length > 0) {
      const hasGreetings = currentGroup.memberIds.some(id => {
        const char = characters.find(c => c.id === id)
        return (char?.groupOnlyGreetings && char.groupOnlyGreetings.length > 0) || char?.firstMessage
      })
      if (hasGreetings) {
        setShowGreetingPicker(true)
      }
    }
  }, [currentGroup?.id, currentSessionId, messages.length])

  const handleSelect = (group: GroupChat) => {
    setSelectedId(group.id)
    selectGroup(group.id)
  }

  const handleCreate = () => {
    setSelectedMemberIds([])
    setMemberSearch('')
    setShowCreateModal(true)
  }

  /** 切换角色选中状态 */
  const toggleMemberSelect = (charId: string) => {
    setSelectedMemberIds(prev =>
      prev.includes(charId) ? prev.filter(id => id !== charId) : [...prev, charId]
    )
  }

  /** 确认创建群聊：群聊名称按角色名逐个拼接 */
  const confirmCreate = async () => {
    if (selectedMemberIds.length === 0) return
    const memberNames = selectedMemberIds
      .map(id => characters.find(c => c.id === id)?.name ?? '未知')
      .join('、')
    const newGroup: GroupChat = {
      id: nanoid(),
      name: memberNames,
      memberIds: [...selectedMemberIds],
      currentSpeakerIndex: 0,
      autoMode: false,
      chatMode: 'polling',
      maxRounds: 1,
      speakerInterval: 2000,
      lorebookIds: [],
      presetId: 'builtin-default',
      systemPrompt: '',
      createdAt: Date.now(),
      updatedAt: Date.now(),
    }
    await saveGroup(newGroup)
    setSelectedId(newGroup.id)
    selectGroup(newGroup.id)
    setShowCreateModal(false)
    setSelectedMemberIds([])
  }

  const handleDelete = async () => {
    if (!deletingId) return
    await deleteGroup(deletingId)
    setShowDeleteConfirm(false)
    setDeletingId(null)
    setSelectedId(null)
  }

  const confirmDelete = (id: string) => {
    setDeletingId(id)
    setShowDeleteConfirm(true)
  }

  const handleRename = async () => {
    if (!currentGroup || !nameDraft.trim()) return
    await saveGroup({ ...currentGroup, name: nameDraft.trim() })
    setEditingName(false)
  }

  const startEditName = () => {
    if (!currentGroup) return
    setNameDraft(currentGroup.name)
    setEditingName(true)
  }

  const handleAddMember = async (charId: string) => {
    if (!currentGroup) return
    if (currentGroup.memberIds.includes(charId)) return
    await saveGroup({
      ...currentGroup,
      memberIds: [...currentGroup.memberIds, charId],
    })
  }

  const handleRemoveMember = async (charId: string) => {
    if (!currentGroup) return
    await saveGroup({
      ...currentGroup,
      memberIds: currentGroup.memberIds.filter(id => id !== charId),
      // L-02 修复：确保 currentSpeakerIndex 不为负数
      currentSpeakerIndex: Math.max(0, Math.min(currentGroup.currentSpeakerIndex, currentGroup.memberIds.length - 2)),
    })
  }

  const handleMoveMember = async (index: number, dir: number) => {
    if (!currentGroup) return
    const newIds = [...currentGroup.memberIds]
    const target = index + dir
    if (target < 0 || target >= newIds.length) return
    ;[newIds[index], newIds[target]] = [newIds[target], newIds[index]]
    await saveGroup({ ...currentGroup, memberIds: newIds })
  }

  // 会话操作
  const openSettings = async () => {
    setShowSettings(true)
    try {
      const [lbs, prs] = await Promise.all([
        window.api.lorebook.list(),
        window.api.preset.list(),
      ])
      setLorebooks(lbs)
      setPresets(prs)
    } catch { /* ignore */ }
  }

  const toggleLorebook = async (id: string) => {
    if (!currentGroup) return
    const ids = currentGroup.lorebookIds.includes(id)
      ? currentGroup.lorebookIds.filter(lid => lid !== id)
      : [...currentGroup.lorebookIds, id]
    await saveGroup({ ...currentGroup, lorebookIds: ids })
  }

  // 导出
  const handleExport = async () => {
    if (!currentGroup || !currentSessionId) return
    try {
      const content = await window.api.group.exportChat(currentGroup.id, currentSessionId, 'md')
      downloadFile(content, `${currentGroup.name}-群聊.md`)
    } catch { /* ignore */ }
  }

  // 角色搜索过滤
  const filteredCharacters = memberSearch.trim()
    ? characters.filter(c =>
        c.name.toLowerCase().includes(memberSearch.toLowerCase()) ||
        (c.description && c.description.toLowerCase().includes(memberSearch.toLowerCase())) ||
        (c.tags && c.tags.some(t => t.toLowerCase().includes(memberSearch.toLowerCase())))
      )
    : characters

  return (
    <div className="flex-1 flex overflow-hidden">
      {/* ============ 左栏：群聊列表（可收起） ============ */}
      <aside className={cn(
        'border-r border-tavern-border-soft bg-tavern-bg-soft flex flex-col shrink-0 transition-all duration-200',
        sidebarCollapsed ? 'w-0 overflow-hidden' : 'w-64'
      )}>
        <div className="flex items-center justify-between px-3 py-2.5 border-b border-tavern-border-soft">
          <span className="text-xs font-medium text-tavern-text-muted">群聊列表</span>
          <div className="flex items-center gap-0.5">
            <button
              onClick={handleCreate}
              className="btn-ghost p-1 rounded-lg hover:bg-tavern-accent-soft hover:text-tavern-accent"
              title="新建群聊"
            >
              <Plus className="w-4 h-4" />
            </button>
            <button
              onClick={() => setSidebarCollapsed(true)}
              className="btn-ghost p-1 rounded-lg hover:bg-tavern-bg-hover text-tavern-text-muted"
              title="收起列表"
            >
              <PanelLeftClose className="w-4 h-4" />
            </button>
          </div>
        </div>

        <div className="flex-1 overflow-y-auto py-1">
          {groupChats.length === 0 ? (
            <div className="px-4 py-8 text-center text-xs text-tavern-text-muted">
              暂无群聊，点击 + 创建
            </div>
          ) : (
            groupChats.map(g => (
              <div
                key={g.id}
                onClick={() => handleSelect(g)}
                role="button"
                tabIndex={0}
                onKeyDown={e => e.key === 'Enter' && handleSelect(g)}
                className={cn(
                  'w-full flex items-center justify-between px-3 py-2.5 text-left hover:bg-tavern-bg-hover transition-colors group cursor-pointer',
                  selectedId === g.id && 'bg-tavern-accent-soft border-r-2'
                )}
                style={selectedId === g.id && g.themeColor ? { borderRightColor: g.themeColor } : undefined}
              >
                <div className="flex-1 min-w-0">
                  <div className="text-sm font-medium text-tavern-text truncate flex items-center gap-1.5">
                    {g.themeColor && (
                      <span
                        className="w-2 h-2 rounded-full shrink-0 inline-block"
                        style={{ backgroundColor: g.themeColor }}
                      />
                    )}
                    {g.name}
                  </div>
                  <div className="text-[10px] text-tavern-text-muted">
                    {g.memberIds.length} 位成员
                    {g.autoMode && ' · 自动'}
                  </div>
                </div>
                <button
                  onClick={(e) => { e.stopPropagation(); confirmDelete(g.id) }}
                  className="p-1 rounded hover:bg-tavern-danger/20 text-tavern-text-muted hover:text-tavern-danger transition-all"
                  title="删除群聊"
                >
                  <Trash2 className="w-3.5 h-3.5" />
                </button>
              </div>
            ))
          )}
        </div>
      </aside>

      {/* ============ 右栏：群聊对话或配置 ============ */}
      <main
        className="flex-1 flex flex-col overflow-hidden bg-tavern-bg relative"
        style={currentGroup?.themeColor ? { '--gc-theme': currentGroup.themeColor } as React.CSSProperties : undefined}
      >
        {/* 收起状态下的展开按钮（始终可见，放在 main 顶部不遮挡内容） */}
        {sidebarCollapsed && !currentGroup && (
          <button
            onClick={() => setSidebarCollapsed(false)}
            className="absolute top-2 left-2 z-30 p-1.5 rounded-lg bg-tavern-bg-soft border border-tavern-border-soft text-tavern-text-muted hover:text-tavern-text hover:bg-tavern-bg-hover transition-colors shadow-sm"
            title="展开群聊列表"
          >
            <PanelLeftOpen className="w-4 h-4" />
          </button>
        )}
        {/* 聊天背景 */}
        {currentGroup?.chatBackgroundParams && (
          <div
            className="absolute inset-0 z-0 pointer-events-none"
            style={{
              opacity: currentGroup.chatBackgroundParams.opacity ?? 0,
              filter: `blur(${currentGroup.chatBackgroundParams.blur ?? 0}px)`,
              background: currentGroup.chatBackgroundParams.type === 'gradient'
                ? (currentGroup.chatBackgroundParams.gradient || undefined)
                : currentGroup.chatBackground
                  ? `url(${currentGroup.chatBackground}) center/cover no-repeat`
                  : undefined,
            }}
          />
        )}
        {!currentGroup ? (
          <div className="flex-1 flex items-center justify-center">
            <EmptyState
              icon={<Users className="w-8 h-8" />}
              title="选择一个群聊"
              description="从左侧选择已有群聊，或创建新的群聊"
              action={
                <button onClick={handleCreate} className="btn-primary">
                  <Plus className="w-4 h-4" />
                  新建群聊
                </button>
              }
            />
          </div>
        ) : (
          <>
            {/* ---- 顶栏 ---- */}
            <header
              className="flex items-center justify-between px-4 h-12 border-b border-tavern-border-soft bg-tavern-bg-soft shrink-0 relative z-10"
              style={currentGroup?.themeColor ? { borderBottomColor: currentGroup.themeColor, borderBottomWidth: '2px' } : undefined}
            >
              <div className="flex items-center gap-2 min-w-0">
                {sidebarCollapsed && (
                  <button
                    onClick={() => setSidebarCollapsed(false)}
                    className="btn-ghost p-1 rounded-lg hover:bg-tavern-bg-hover text-tavern-text-muted shrink-0"
                    title="展开群聊列表"
                  >
                    <PanelLeftOpen className="w-4 h-4" />
                  </button>
                )}
                {editingName ? (
                  <div className="flex items-center gap-1">
                    <input
                      value={nameDraft}
                      onChange={e => setNameDraft(e.target.value)}
                      onKeyDown={e => e.key === 'Enter' && handleRename()}
                      className="w-32 bg-tavern-bg border border-tavern-border rounded px-2 py-0.5 text-sm text-tavern-text outline-none focus:border-tavern-accent"
                      autoFocus
                      onBlur={handleRename}
                    />
                    <button onClick={handleRename} className="p-1 text-tavern-accent">
                      <Check className="w-3.5 h-3.5" />
                    </button>
                  </div>
                ) : (
                  <>
                    <h2 className="font-display text-sm font-bold text-tavern-text truncate">{currentGroup.name}</h2>
                    <button onClick={startEditName} className="p-1 text-tavern-text-muted hover:text-tavern-text">
                      <Edit2 className="w-3 h-3" />
                    </button>
                  </>
                )}

                {/* ---- 会话管理 ---- */}
                <SessionSwitcher
                  sessions={sessions}
                  currentSessionId={currentSessionId}
                  variant="group"
                  onSwitch={(id) => switchSession(currentGroup.id, id)}
                  onRename={(id, title) => renameSession(currentGroup.id, id, title)}
                  onDelete={(id) => deleteSession(currentGroup.id, id)}
                  onCreate={() => createSession(currentGroup.id)}
                />
              </div>

              <div className="flex items-center gap-1">
                {/* 字符总量 */}
                {(() => {
                  const totalChars = messages.reduce((sum, m) => sum + (m.charUsage?.totalChars ?? 0), 0)
                  if (totalChars > 0) {
                    return (
                      <span className="text-[10px] text-tavern-text-muted px-1.5 py-0.5 rounded bg-tavern-bg-hover">
                        {totalChars} 字符
                      </span>
                    )
                  }
                  return null
                })()}

                {/* 长记忆 */}
                {currentSessionId && (
                  <MemoryPanel
                    open={showMemoryPanel}
                    onToggle={() => {
                      if (!showMemoryPanel && currentSessionId) {
                        const curS = sessions.find(s => s.id === currentSessionId)
                        setMemoryInterval(curS?.autoMemoryInterval ?? 10)
                      }
                      setShowMemoryPanel(!showMemoryPanel)
                    }}
                    sessions={sessions}
                    currentSessionId={currentSessionId}
                    currentCharacterId={currentGroup?.id ?? null}
                    memoryInterval={memoryInterval}
                    onMemoryIntervalChange={setMemoryInterval}
                    onToggleMemory={(enabled) => {
                      if (currentGroup && currentSessionId) toggleMemory(currentGroup.id, currentSessionId, enabled)
                    }}
                    onSetMemoryMode={(mode, interval) => {
                      if (currentGroup && currentSessionId) setMemoryMode(currentGroup.id, currentSessionId, mode, interval)
                    }}
                    onTriggerSummary={() => {
                      triggerMemorySummary()
                    }}
                    isStreaming={isStreaming}
                    memoryStats={messages.length > 0 ? {
                      totalMessages: messages.length,
                      totalChars: messages.reduce((sum, m) => sum + (m.content?.length ?? 0), 0),
                      durationStr: messages.length > 1
                        ? (() => {
                            const ms = messages[messages.length - 1].timestamp - messages[0].timestamp
                            const hours = Math.floor(ms / 3600000)
                            const mins = Math.floor((ms % 3600000) / 60000)
                            return hours > 0 ? `${hours}小时${mins}分钟` : `${mins}分钟`
                          })()
                        : '不足1分钟',
                    } : null}
                  />
                )}

                <button
                  onClick={() => {
                    const ctx = useGroupChatStore.getState().buildGroupContext()
                    setContextContent(ctx)
                    setShowContextViewer(true)
                  }}
                  className="btn-ghost p-1.5 text-xs text-tavern-text-muted hover:text-tavern-text"
                  title="查看上下文"
                >
                  <Eye className="w-3.5 h-3.5" />
                </button>
                <button
                  onClick={() => setShowClearConfirm(true)}
                  className="btn-ghost p-1.5 text-xs text-tavern-text-muted hover:text-tavern-danger"
                  title="清空聊天"
                >
                  <Trash2 className="w-3.5 h-3.5" />
                </button>
                <button
                  onClick={() => openSettings()}
                  className="btn-ghost p-1.5 text-xs text-tavern-text-muted hover:text-tavern-text"
                  title="群聊设置"
                >
                  <Settings2 className="w-3.5 h-3.5" />
                </button>
              </div>
            </header>

            {/* ---- 消息区域 ---- */}
            <div className="flex-1 overflow-hidden relative z-0">
              {messages.length === 0 && !isStreaming ? (
                <div className="flex items-center justify-center h-full text-xs text-tavern-text-muted">
                  <div className="text-center">
                    <MessageSquare className="w-8 h-8 mx-auto mb-2 opacity-30" />
                    <p>选择成员并开始群聊对话</p>
                  </div>
                </div>
              ) : (
                <Virtuoso
                  key={currentGroup?.id || 'default'}
                  ref={virtuosoRef}
                  data={messages}
                  className="h-full"
                  followOutput="smooth"
                  itemContent={(index, m) => {
                    const memberIdx = currentGroup.memberIds.indexOf(m.characterId)
                    const isAiMsg = m.characterId !== '__user__'
                    const isStreamingMsg = isStreaming && index === messages.length - 1 && isAiMsg
                    // 查找被引用的消息
                    const repliedMessage = m.replyToId
                      ? messages.find(msg => msg.id === m.replyToId)
                      : undefined
                    return (
                      <GroupChatMessage
                        key={m.id}
                        message={m}
                        memberIndex={memberIdx}
                        isStreamingMessage={isStreamingMsg}
                        repliedMessage={repliedMessage}
                        bubbleOpacity={currentGroup.bubbleOpacity}
                        onReply={
                          !isStreaming ? () => setReplyToMessage(m) : undefined
                        }
                        onDelete={
                          !currentSessionId || isStreaming ? undefined : () => deleteMessage(currentGroup.id, currentSessionId!, m.id)
                        }
                        onEdit={
                          !currentSessionId || isStreaming ? undefined : (content: string) => editMessage(currentGroup.id, currentSessionId!, m.id, content)
                        }
                        onRegenerate={
                          isAiMsg && !isStreaming ? () => regenerateMessage(m.id) : undefined
                        }
                        onTranslate={
                          !isStreaming ? () => translateMessage(m.id) : undefined
                        }
                      />
                    )
                  }}
                  components={{
                    Footer: () => <div className="h-4" />,
                  }}
                />
              )}
            </div>

            {/* ---- 输入区 ---- */}
            <div className="relative z-10">
            <GroupChatInput
              group={currentGroup}
              replyTo={replyToMessage}
              onCancelReply={() => setReplyToMessage(null)}
            />
            </div>

            {/* ---- 成员栏 ---- */}
            <div className="relative z-10">
            <GroupMemberBar
              memberIds={currentGroup.memberIds}
              currentSpeakerIndex={currentGroup.currentSpeakerIndex}
              themeColor={currentGroup.themeColor}
              onSpeakerClick={(charId) => {
                const idx = currentGroup.memberIds.indexOf(charId)
                if (idx < 0) return
                // 更新当前发言者索引
                const updated = { ...currentGroup, currentSpeakerIndex: idx }
                saveGroup(updated)
                // polling 模式且非自动时，手动触发该角色发言
                if (currentGroup.chatMode === 'polling' && !currentGroup.autoMode && !isStreaming) {
                  sendPollingRound(charId)
                }
              }}
            />
            </div>
          </>
        )}
      </main>

      {/* ============ 群聊设置弹窗 ============ */}
      {showSettings && currentGroup && (
        <GroupChatSettingsPanel
          group={currentGroup}
          characters={characters}
          lorebooks={lorebooks}
          presets={presets}
          onClose={() => setShowSettings(false)}
          onSave={saveGroup}
          onDelete={() => confirmDelete(currentGroup.id)}
          onAddMember={handleAddMember}
          onRemoveMember={handleRemoveMember}
          onMoveMember={handleMoveMember}
          onToggleLorebook={toggleLorebook}
          onExport={handleExport}
        />
      )}

      {/* ============ 删除群聊确认 ============ */}
      <ConfirmDialog
        open={showDeleteConfirm}
        title="删除群聊"
        message="确定要删除此群聊吗？所有群聊对话数据将被清除，此操作不可撤销。"
        onConfirm={handleDelete}
        onClose={() => { setShowDeleteConfirm(false); setDeletingId(null) }}
        danger
      />

      {/* ============ 清空聊天确认 ============ */}
      <ConfirmDialog
        open={showClearConfirm}
        title="清空聊天"
        message="确定要清空当前会话的所有聊天记录吗？此操作不可撤销。"
        onConfirm={async () => {
          if (currentGroup) {
            await clearChat(currentGroup.id)
          }
          setShowClearConfirm(false)
        }}
        onClose={() => setShowClearConfirm(false)}
        danger
      />

      {/* ============ 上下文查看器 ============ */}
      <Modal
        open={showContextViewer}
        onClose={() => setShowContextViewer(false)}
        width="xl"
        headerClassName="px-4 py-3 bg-tavern-bg-soft"
        header={
          <div className="flex items-center gap-2 flex-1">
            <h3 className="text-sm font-semibold text-tavern-text">上下文查看器</h3>
            <span className="text-[10px] text-tavern-text-muted">{contextContent.length} 条消息</span>
          </div>
        }
        contentClassName="p-4"
      >
        <div className="space-y-3">
          {contextContent.map((item, i) => (
            <div key={i} className="space-y-1">
              <span className={cn(
                'text-[10px] font-medium px-1.5 py-0.5 rounded',
                item.role === 'system' ? 'bg-purple-500/10 text-purple-400' :
                item.role === 'user' ? 'bg-blue-500/10 text-blue-400' :
                'bg-emerald-500/10 text-emerald-400'
              )}>
                {item.role.toUpperCase()}
              </span>
              <pre className="text-xs text-tavern-text whitespace-pre-wrap font-mono bg-tavern-bg rounded-lg p-3 max-h-40 overflow-y-auto border border-tavern-border-soft/50">
                {item.content}
              </pre>
            </div>
          ))}
        </div>
      </Modal>

      {/* ============ 群聊开场白选择弹窗 ============ */}
      <GreetingPickerModal
        open={showGreetingPicker}
        group={currentGroup}
        messagesCount={messages.length}
        isStreaming={isStreaming}
        onClose={() => setShowGreetingPicker(false)}
      />

      {/* 空状态时不显示弹窗的自动触发提示：如果没有消息，自动弹出选择器 */}
      {currentGroup && messages.length === 0 && !isStreaming && !showGreetingPicker && (() => {
        const hasGreetings = currentGroup.memberIds.some(id => {
          const char = characters.find(c => c.id === id)
          return (char?.groupOnlyGreetings && char.groupOnlyGreetings.length > 0) || char?.firstMessage
        })
        if (!hasGreetings) return null
        return (
          <div className="absolute bottom-32 left-1/2 -translate-x-1/2 z-10">
            <button
              onClick={() => setShowGreetingPicker(true)}
              className="px-4 py-2 rounded-xl text-white text-xs font-medium shadow-lg hover:shadow-xl transition-all bg-tavern-accent"
              style={currentGroup.themeColor ? { backgroundColor: currentGroup.themeColor } : undefined}
            >
              选择开场白
            </button>
          </div>
        )
      })()}

      {/* ============ 新建群聊：角色选择弹窗 ============ */}
      <NewGroupModal
        open={showCreateModal}
        characters={characters}
        filteredCharacters={filteredCharacters}
        selectedMemberIds={selectedMemberIds}
        memberSearch={memberSearch}
        onMemberSearchChange={setMemberSearch}
        onToggleMember={toggleMemberSelect}
        onCreate={confirmCreate}
        onClose={() => setShowCreateModal(false)}
      />

    </div>
  )
}

import { useEffect, useRef, useState } from 'react'
import { nanoid } from 'nanoid'
import { EmptyState } from '../components/common/EmptyState'
import { ConfirmDialog } from '../components/common/ConfirmDialog'
import { cn } from '../lib/utils'
import { logError } from '../lib/logger'
import {
  BookOpen,
  BookMarked,
  Plus,
  Upload,
  Trash2,
  Pencil,
  Languages,
  Loader2,
  ChevronDown,
  ChevronUp,
  X,
  Brain,
  CircleCheck,
  CircleAlert,
} from 'lucide-react'
import { useSettingsStore } from '../store/useSettingsStore'
import type { Lorebook, LoreEntry } from '../../shared/types'

const POSITION_LABELS: Record<LoreEntry['position'], string> = {
  before_char: '角色定义前',
  after_char: '角色定义后',
  at_depth: '历史消息中（按深度）',
  at_end: '消息末尾',
}

const MATCH_MODE_LABELS: Record<NonNullable<LoreEntry['matchMode']>, string> = {
  keyword: '关键词',
  semantic: '语义（向量）',
  both: '关键词 + 语义',
}

function Toggle({ checked, onChange }: { checked: boolean; onChange: (v: boolean) => void }) {
  return (
    <button
      type="button"
      onClick={() => onChange(!checked)}
      className={cn(
        'relative inline-flex h-5 w-9 shrink-0 items-center rounded-full transition-colors',
        checked ? 'bg-tavern-accent' : 'bg-tavern-bg-hover'
      )}
    >
      <span
        className={cn(
          'inline-block h-4 w-4 transform rounded-full bg-white transition-transform',
          checked ? 'translate-x-4' : 'translate-x-0.5'
        )}
      />
    </button>
  )
}

function createLorebook(): Lorebook {
  return {
    id: nanoid(),
    name: '新建世界书',
    description: '',
    entries: [],
    enabled: true,
    scanDepth: 4,
  }
}

function createEntry(): LoreEntry {
  return {
    id: nanoid(),
    keywords: [],
    content: '',
    position: 'before_char',
    order: 100,
    probability: 100,
    enabled: true,
    matchMode: 'both',
  }
}

export function LorebookPage() {
  const [lorebooks, setLorebooks] = useState<Lorebook[]>([])
  const [selectedId, setSelectedId] = useState<string | null>(null)
  const [editingEntry, setEditingEntry] = useState<LoreEntry | null>(null)
  const [deleteId, setDeleteId] = useState<string | null>(null)
  const [deleteEntryId, setDeleteEntryId] = useState<string | null>(null)
  const [expandedEntries, setExpandedEntries] = useState<Set<string>>(new Set())
  /** AI 翻译状态：key 为字段标识 */
  const [translatingField, setTranslatingField] = useState<{ key: string; text: string } | null>(null)
  const [translateResult, setTranslateResult] = useState<string | null>(null)
  /** 语义触发：向量索引状态（lorebookId -> 已索引条目数等） */
  const [indexStatus, setIndexStatus] = useState<Record<string, { indexed: number; model: string; updatedAt: number; stale: number }>>({})
  const [indexingId, setIndexingId] = useState<string | null>(null)
  const [indexError, setIndexError] = useState<string | null>(null)

  const { getActiveProfile, settings } = useSettingsStore()

  /** H-09 修复：追踪活跃的 AI 请求 ID，组件卸载时取消并清理监听器 */
  const activeRequestIdsRef = useRef<Set<string>>(new Set())

  useEffect(() => {
    return () => {
      const ids = Array.from(activeRequestIdsRef.current)
      for (const id of ids) {
        window.api.ai.cancelChat(id).catch((e) => logError('LorebookPage:cancelChat', e))
      }
      activeRequestIdsRef.current.clear()
    }
  }, [])

  const selected = lorebooks.find((l) => l.id === selectedId) ?? null

  useEffect(() => {
    window.api.lorebook.list().then((list) => {
      setLorebooks(list)
      if (list.length > 0) setSelectedId(list[0].id)
      refreshIndexStatus(list.map((l) => l.id))
    })
  }, [])

  /** 刷新向量索引状态 */
  const refreshIndexStatus = async (ids: string[]) => {
    if (ids.length === 0) return
    try {
      const status = await window.api.embedding.indexStatus(ids)
      setIndexStatus(status)
    } catch { /* 忽略 */ }
  }

  /** 为当前世界书生成/重建向量索引 */
  const handleIndexLorebook = async () => {
    if (!selected || indexingId) return
    const st = settings.semanticTrigger
    if (!st) {
      setIndexError('请先在「设置 → 语义触发」中配置嵌入服务')
      return
    }
    setIndexingId(selected.id)
    setIndexError(null)
    try {
      const result = await window.api.embedding.indexLorebook(selected.id, {
        provider: st.provider,
        baseUrl: st.baseUrl,
        model: st.model,
        apiKey: st.apiKey ?? '',
      })
      if (!result.ok) {
        setIndexError(result.error || '索引失败')
      }
      await refreshIndexStatus([selected.id])
    } catch (e) {
      setIndexError((e as Error).message)
    } finally {
      setIndexingId(null)
    }
  }

  const updateLorebook = (id: string, patch: Partial<Lorebook>) => {
    const current = lorebooks.find((l) => l.id === id)
    if (!current) return
    const updated: Lorebook = { ...current, ...patch }
    setLorebooks((prev) => prev.map((l) => (l.id === id ? updated : l)))
    window.api.lorebook.save(updated)
  }

  const handleNew = () => {
    const lb = createLorebook()
    setLorebooks((prev) => [...prev, lb])
    setSelectedId(lb.id)
    setEditingEntry(null)
    window.api.lorebook.save(lb)
  }

  const handleImport = async () => {
    const imported = await window.api.lorebook.importJson()
    if (imported) {
      setLorebooks((prev) => [...prev, imported])
      setSelectedId(imported.id)
      setEditingEntry(null)
    }
  }

  const handleDelete = async () => {
    if (!deleteId) return
    await window.api.lorebook.delete(deleteId)
    setLorebooks((prev) => prev.filter((l) => l.id !== deleteId))
    if (selectedId === deleteId) setSelectedId(null)
    setDeleteId(null)
  }

  const handleNewEntry = () => {
    setEditingEntry(createEntry())
  }

  const handleEditEntry = (entry: LoreEntry) => {
    setEditingEntry({ ...entry })
  }

  const handleSaveEntry = () => {
    if (!editingEntry || !selected) return
    const exists = selected.entries.some((e) => e.id === editingEntry.id)
    const entries = exists
      ? selected.entries.map((e) => (e.id === editingEntry.id ? editingEntry : e))
      : [...selected.entries, editingEntry]
    updateLorebook(selected.id, { entries })
    setEditingEntry(null)
  }

  const handleDeleteEntry = () => {
    if (!deleteEntryId || !selected) return
    const entries = selected.entries.filter((e) => e.id !== deleteEntryId)
    updateLorebook(selected.id, { entries })
    if (editingEntry?.id === deleteEntryId) setEditingEntry(null)
    setDeleteEntryId(null)
  }

  /** AI 翻译文本并在目标字段中应用 */
  const handleAiTranslate = async (text: string, fieldKey: string, onApply: (translated: string) => void) => {
    if (!text.trim() || translatingField) return
    const profile = getActiveProfile()
    if (!profile) return

    setTranslatingField({ key: fieldKey, text })
    setTranslateResult(null)

    const requestId = `lorebook-translate-${Date.now()}`
    activeRequestIdsRef.current.add(requestId)
    let result = ''

    const cleanup = () => {
      activeRequestIdsRef.current.delete(requestId)
      unbindChunk(); unbindDone(); unbindError()
    }

    const unbindChunk = window.api.ai.onChunk((data) => {
      if (data.requestId !== requestId) return
      result += data.text
      setTranslateResult(result.replace(/<thought>[\s\S]*?<\/thought>/gi, '').replace(/<thinking>[\s\S]*?<\/thinking>/gi, '').trim())
    })
    const unbindDone = window.api.ai.onDone((doneId) => {
      if (doneId !== requestId) return
      cleanup()
      setTranslatingField(null)
      setTranslateResult(null)
      if (result.trim()) {
        // 剥离 <thought> / <thinking> 标签，避免 AI 将思考过程混入翻译结果
        const cleanResult = result
          .replace(/<thought>[\s\S]*?<\/thought>/gi, '')
          .replace(/<thinking>[\s\S]*?<\/thinking>/gi, '')
          .trim()
        if (cleanResult) {
          onApply(cleanResult)
        }
      }
    })
    const unbindError = window.api.ai.onError((data) => {
      if (data.requestId !== requestId) return
      cleanup()
      setTranslatingField(null)
      setTranslateResult(null)
    })

    const targetLang = settings.translationTargetLang || '中文'
    window.api.ai.chat({
      requestId,
      messages: [
        { role: 'system', content: `你是一个翻译助手。请将以下文本翻译成${targetLang}。只输出翻译结果，不要添加任何解释或额外内容。保留原文中的标点符号风格。` },
        { role: 'user', content: text },
      ],
      provider: profile.provider,
      apiKey: profile.apiKey,
      baseUrl: profile.baseUrl,
      model: settings.activeModel || profile.model,
      temperature: 0.3,
      topP: 0.9,
      maxTokens: 2048,
      frequencyPenalty: 0,
      presencePenalty: 0,
      stream: true,
    }).catch(() => {
      cleanup()
      setTranslatingField(null)
      setTranslateResult(null)
    })
  }

  const toggleEntryExpand = (entryId: string) => {
    setExpandedEntries((prev) => {
      const next = new Set(prev)
      if (next.has(entryId)) next.delete(entryId)
      else next.add(entryId)
      return next
    })
  }

  return (
    <div className="flex-1 flex flex-col overflow-hidden">
      {/* 顶栏 */}
      <header className="flex items-center justify-between px-4 h-14 border-b border-tavern-border-soft bg-tavern-bg-soft shrink-0">
        <h1 className="font-display text-lg font-bold">世界书</h1>
        <div className="flex items-center gap-2">
          <button onClick={handleNew} className="btn-primary">
            <Plus className="w-4 h-4" />
            新建
          </button>
          <button onClick={handleImport} className="btn-secondary">
            <Upload className="w-4 h-4" />
            导入
          </button>
        </div>
      </header>

      {lorebooks.length === 0 ? (
        <EmptyState
          className="h-full"
          icon={<BookOpen className="w-8 h-8" />}
          title="还没有世界书"
          description="创建你的第一本世界书，为角色扮演添加丰富的世界观设定"
          action={
            <div className="flex gap-2">
              <button className="btn-primary" onClick={handleNew}>
                <Plus className="w-4 h-4" />
                新建世界书
              </button>
              <button className="btn-secondary" onClick={handleImport}>
                <Upload className="w-4 h-4" />
                导入世界书
              </button>
            </div>
          }
        />
      ) : (
        <div className="flex-1 flex overflow-hidden">
          {/* 左侧列表 */}
          <aside className="w-72 border-r border-tavern-border-soft overflow-y-auto p-3 space-y-2 shrink-0">
            {lorebooks.map((lb) => (
              <div
                key={lb.id}
                onClick={() => {
                  setSelectedId(lb.id)
                  setEditingEntry(null)
                }}
                className={cn(
                  'card p-3 cursor-pointer transition-colors',
                  lb.id === selectedId
                    ? 'border-tavern-accent ring-1 ring-tavern-accent'
                    : 'hover:bg-tavern-bg-hover'
                )}
              >
                <div className="flex items-start justify-between gap-2">
                  <div className="min-w-0 flex-1">
                    <div className="flex items-center gap-2">
                      <BookMarked className="w-4 h-4 text-tavern-accent shrink-0" />
                      <span className="font-medium text-sm text-tavern-text truncate">
                        {lb.name}
                      </span>
                    </div>
                    <p className="text-xs text-tavern-text-muted mt-1 line-clamp-2">
                      {lb.description || '无描述'}
                    </p>
                    <div className="text-xs text-tavern-text-muted mt-1.5">
                      {lb.entries.length} 个条目
                    </div>
                  </div>
                  <div onClick={(e) => e.stopPropagation()}>
                    <Toggle
                      checked={lb.enabled}
                      onChange={(v) => updateLorebook(lb.id, { enabled: v })}
                    />
                  </div>
                </div>
              </div>
            ))}
          </aside>

          {/* 右侧编辑区 */}
          <div className="flex-1 flex flex-col overflow-hidden">
            {!selected ? (
              <EmptyState
                className="h-full"
                icon={<BookOpen className="w-8 h-8" />}
                title="选择一本世界书"
                description="从左侧选择一本世界书来编辑其条目"
              />
            ) : (
              <>
                {/* 世界书信息 */}
                <div className="p-4 border-b border-tavern-border-soft space-y-3 shrink-0">
                  <div className="flex items-start gap-3">
                    <div className="flex-1 grid grid-cols-2 gap-3">
                      <div>
                        <label className="label">名称</label>
                        <div className="flex gap-1.5">
                          <input
                            className="input flex-1"
                            value={selected.name}
                            onChange={(e) => updateLorebook(selected.id, { name: e.target.value })}
                          />
                          <button
                            className="btn-ghost p-1.5 shrink-0"
                            title="AI 翻译名称"
                            disabled={!!translatingField}
                            onClick={() => handleAiTranslate(selected.name, `name-${selected.id}`, (translated) => {
                              updateLorebook(selected.id, { name: translated })
                            })}
                          >
                            {translatingField?.key === `name-${selected.id}` ? (
                              <Loader2 className="w-3.5 h-3.5 animate-spin" />
                            ) : (
                              <Languages className="w-3.5 h-3.5" />
                            )}
                          </button>
                        </div>
                      </div>
                      <div>
                        <label className="label">扫描深度（最近 N 条消息）</label>
                        <input
                          type="number"
                          min={1}
                          className="input"
                          value={selected.scanDepth}
                          onChange={(e) =>
                            updateLorebook(selected.id, {
                              scanDepth: Number(e.target.value) || 1,
                            })
                          }
                        />
                      </div>
                    </div>
                    <div className="flex items-center gap-2 pt-6">
                      <span className="text-sm text-tavern-text-soft">启用</span>
                      <Toggle
                        checked={selected.enabled}
                        onChange={(v) => updateLorebook(selected.id, { enabled: v })}
                      />
                      <button
                        className="btn-danger"
                        onClick={() => setDeleteId(selected.id)}
                        title="删除世界书"
                      >
                        <Trash2 className="w-4 h-4" />
                      </button>
                    </div>
                  </div>
                  <div>
                    <label className="label">描述</label>
                    <div className="flex gap-1.5">
                      <input
                        className="input flex-1"
                        value={selected.description}
                        onChange={(e) =>
                          updateLorebook(selected.id, { description: e.target.value })
                        }
                      />
                      <button
                        className="btn-ghost p-1.5 shrink-0"
                        title="AI 翻译描述"
                        disabled={!!translatingField || !selected.description}
                        onClick={() => handleAiTranslate(selected.description, `desc-${selected.id}`, (translated) => {
                          updateLorebook(selected.id, { description: translated })
                        })}
                      >
                        {translatingField?.key === `desc-${selected.id}` ? (
                          <Loader2 className="w-3.5 h-3.5 animate-spin" />
                        ) : (
                          <Languages className="w-3.5 h-3.5" />
                        )}
                      </button>
                    </div>
                  </div>

                  {/* 语义触发：向量索引 */}
                  <div className="flex items-center gap-3 pt-1">
                    <button
                      className="btn-secondary text-xs"
                      disabled={indexingId !== null}
                      onClick={handleIndexLorebook}
                      title="为启用且匹配模式包含「语义」的条目生成向量索引（语义触发需在设置中启用）"
                    >
                      {indexingId === selected.id ? (
                        <Loader2 className="w-3.5 h-3.5 animate-spin" />
                      ) : (
                        <Brain className="w-3.5 h-3.5" />
                      )}
                      {indexingId === selected.id ? '索引中...' : '生成语义索引'}
                    </button>
                    {indexStatus[selected.id] && indexStatus[selected.id].indexed > 0 ? (
                      <span className="text-xs text-tavern-text-muted flex items-center gap-1">
                        <CircleCheck className="w-3.5 h-3.5 text-tavern-accent" />
                        已索引 {indexStatus[selected.id].indexed} 个条目
                        <span className="text-tavern-text-muted/60">（{indexStatus[selected.id].model}）</span>
                        {indexStatus[selected.id].stale > 0 && (
                          <span className="text-xs text-tavern-warning flex items-center gap-0.5">
                            <CircleAlert className="w-3 h-3" />
                            {indexStatus[selected.id].stale} 条已过期（内容修改后需重新索引）
                          </span>
                        )}
                      </span>
                    ) : (
                      <span className="text-xs text-tavern-text-muted flex items-center gap-1">
                        <CircleAlert className="w-3.5 h-3.5 text-tavern-text-muted" />
                        未索引（语义触发条目需要先生成索引）
                      </span>
                    )}
                    {indexError && (
                      <span className="text-xs text-tavern-danger">{indexError}</span>
                    )}
                  </div>
                </div>

                {/* 条目列表 */}
                <div className="flex-1 overflow-y-auto p-4">
                  <div className="flex items-center justify-between mb-3">
                    <h3 className="font-medium text-sm text-tavern-text">
                      条目（{selected.entries.length}）
                    </h3>
                    <button className="btn-secondary" onClick={handleNewEntry}>
                      <Plus className="w-4 h-4" />
                      新建条目
                    </button>
                  </div>
                  {selected.entries.length === 0 ? (
                    <div className="text-center py-10 text-sm text-tavern-text-muted">
                      暂无条目，点击「新建条目」开始添加
                    </div>
                  ) : (
                    <div className="space-y-2">
                      {selected.entries.map((entry) => (
                        <div key={entry.id} className="card p-3">
                          <div className="flex items-start justify-between gap-3">
                            <div className="min-w-0 flex-1">
                              <div className="flex flex-wrap gap-1 mb-1.5">
                                {entry.keywords.length === 0 ? (
                                  <span className="text-xs text-tavern-text-muted">无关键词</span>
                                ) : (
                                  entry.keywords.map((k, i) => (
                                    <span
                                      key={i}
                                      className="px-1.5 py-0.5 rounded bg-tavern-accent-soft text-tavern-accent text-xs"
                                    >
                                      {k}
                                    </span>
                                  ))
                                )}
                              </div>
                              <div className="flex items-center gap-2">
                                <button
                                  onClick={() => toggleEntryExpand(entry.id)}
                                  className="text-xs text-tavern-text-muted hover:text-tavern-text flex items-center gap-0.5"
                                  title={expandedEntries.has(entry.id) ? '收起内容' : '展开内容'}
                                >
                                  {expandedEntries.has(entry.id) ? <ChevronUp className="w-3 h-3" /> : <ChevronDown className="w-3 h-3" />}
                                </button>
                                <p className={cn(
                                  'text-xs text-tavern-text-soft',
                                  expandedEntries.has(entry.id) ? '' : 'line-clamp-2'
                                )}>
                                  {entry.content || '无内容'}
                                </p>
                                {/* 翻译内容展示 */}
                                {entry.translation && (
                                  <div className={cn(
                                    'mt-1.5 pl-2 border-l-2 border-tavern-accent',
                                    expandedEntries.has(entry.id) ? '' : 'line-clamp-2'
                                  )}>
                                    <span className="text-xs text-tavern-accent font-medium">翻译：</span>
                                    <p className="text-xs text-tavern-text-soft mt-0.5 whitespace-pre-wrap">
                                      {entry.translation}
                                    </p>
                                  </div>
                                )}
                                {/* 翻译流式预览（条目列表） */}
                                {translatingField?.key === `entry-${entry.id}` && translateResult !== null && (
                                  <div className="mt-1.5 p-2 rounded bg-tavern-bg-hover border border-tavern-border-soft text-xs text-tavern-text-soft max-h-24 overflow-y-auto">
                                    {translateResult || '...'}
                                  </div>
                                )}
                              </div>
                              <div className="flex items-center gap-3 mt-1.5 text-xs text-tavern-text-muted">
                                <span>{POSITION_LABELS[entry.position]}</span>
                                <span>顺序 {entry.order}</span>
                                <span>概率 {entry.probability}%</span>
                                <span className="px-1.5 py-0.5 rounded bg-tavern-bg-hover text-tavern-text-soft">
                                  {MATCH_MODE_LABELS[entry.matchMode ?? 'both']}
                                </span>
                              </div>
                            </div>
                            <div className="flex items-center gap-1 shrink-0">
                              <div onClick={(e) => e.stopPropagation()}>
                                <Toggle
                                  checked={entry.enabled}
                                  onChange={(v) => {
                                    const entries = selected.entries.map((e) =>
                                      e.id === entry.id ? { ...e, enabled: v } : e
                                    )
                                    updateLorebook(selected.id, { entries })
                                  }}
                                />
                              </div>
                              <button
                                className="btn-ghost p-1.5"
                                onClick={() => handleEditEntry(entry)}
                                title="编辑"
                              >
                                <Pencil className="w-4 h-4" />
                              </button>
                              <button
                                className={cn(
                                  'btn-ghost p-1.5',
                                  entry.translation && 'text-tavern-accent'
                                )}
                                title={entry.translation ? 'AI 翻译此条目（已有翻译）' : 'AI 翻译此条目'}
                                disabled={!!translatingField || !entry.content}
                                onClick={() => handleAiTranslate(entry.content, `entry-${entry.id}`, (translated) => {
                                  const entries = selected.entries.map((e) =>
                                    e.id === entry.id ? { ...e, translation: translated } : e
                                  )
                                  updateLorebook(selected.id, { entries })
                                })}
                              >
                                {translatingField?.key === `entry-${entry.id}` ? (
                                  <Loader2 className="w-3.5 h-3.5 animate-spin" />
                                ) : (
                                  <Languages className="w-3.5 h-3.5" />
                                )}
                              </button>
                              <button
                                className="btn-ghost p-1.5 text-tavern-danger"
                                onClick={() => setDeleteEntryId(entry.id)}
                                title="删除"
                              >
                                <Trash2 className="w-4 h-4" />
                              </button>
                            </div>
                          </div>
                        </div>
                      ))}
                    </div>
                  )}
                </div>

                {/* 条目编辑表单 */}
                {editingEntry && (
                  <div className="border-t border-tavern-border-soft bg-tavern-bg-soft p-4 space-y-3 shrink-0 max-h-[55%] overflow-y-auto">
                    <div className="flex items-center justify-between">
                      <h3 className="font-medium text-sm text-tavern-text">
                        {selected.entries.some((e) => e.id === editingEntry.id)
                          ? '编辑条目'
                          : '新建条目'}
                      </h3>
                      <div className="flex items-center gap-2">
                        <button className="btn-ghost" onClick={() => setEditingEntry(null)}>
                          取消
                        </button>
                        <button className="btn-primary" onClick={handleSaveEntry}>
                          保存条目
                        </button>
                      </div>
                    </div>
                    <div className="grid grid-cols-2 gap-3">
                      <div className="col-span-2">
                        <label className="label">关键词（逗号分隔）</label>
                        <input
                          className="input"
                          placeholder="例如：魔法,世界,设定"
                          value={editingEntry.keywords.join(',')}
                          onChange={(e) =>
                            setEditingEntry({
                              ...editingEntry,
                              keywords: e.target.value
                                .split(',')
                                .map((s) => s.trim())
                                .filter(Boolean),
                            })
                          }
                        />
                      </div>
                      <div className="col-span-2">
                        <label className="label">内容</label>
                        <div className="flex gap-1.5 items-start">
                          <textarea
                            className="textarea h-24 flex-1"
                            placeholder="当关键词被触发时插入的内容..."
                            value={editingEntry.content}
                            onChange={(e) =>
                              setEditingEntry({ ...editingEntry, content: e.target.value })
                            }
                          />
                          <button
                            className="btn-ghost p-1.5 shrink-0"
                            title="AI 翻译内容"
                            disabled={!!translatingField || !editingEntry.content}
                            onClick={() => handleAiTranslate(editingEntry.content, `edit-${editingEntry.id}`, (translated) => {
                              setEditingEntry({ ...editingEntry, translation: translated })
                            })}
                          >
                            {translatingField?.key === `edit-${editingEntry.id}` ? (
                              <Loader2 className="w-3.5 h-3.5 animate-spin" />
                            ) : (
                              <Languages className="w-3.5 h-3.5" />
                            )}
                          </button>
                        </div>
                        {/* 翻译流式预览 */}
                        {translatingField?.key === `edit-${editingEntry.id}` && translateResult !== null && (
                          <div className="mt-1.5 p-2 rounded bg-tavern-bg-hover border border-tavern-border-soft text-xs text-tavern-text-soft max-h-24 overflow-y-auto">
                            {translateResult || '...'}
                          </div>
                        )}
                        {/* 已有翻译结果展示 */}
                        {editingEntry.translation && translatingField?.key !== `edit-${editingEntry.id}` && (
                          <div className="mt-1.5 flex items-start gap-2 p-2 rounded bg-tavern-bg-hover border border-tavern-border-soft">
                            <div className="flex-1 min-w-0">
                              <span className="text-xs text-tavern-accent font-medium">翻译结果：</span>
                              <p className="text-xs text-tavern-text-soft mt-0.5 whitespace-pre-wrap">
                                {editingEntry.translation}
                              </p>
                            </div>
                            <button
                              className="btn-ghost p-0.5 shrink-0 text-tavern-text-muted hover:text-tavern-danger"
                              title="清除翻译"
                              onClick={() => setEditingEntry({ ...editingEntry, translation: undefined })}
                            >
                              <X className="w-3.5 h-3.5" />
                            </button>
                          </div>
                        )}
                      </div>
                      <div>
                        <label className="label">插入位置</label>
                        <select
                          className="select"
                          value={editingEntry.position}
                          onChange={(e) =>
                            setEditingEntry({
                              ...editingEntry,
                              position: e.target.value as LoreEntry['position'],
                            })
                          }
                        >
                          <option value="before_char">{POSITION_LABELS.before_char}</option>
                          <option value="after_char">{POSITION_LABELS.after_char}</option>
                          <option value="at_depth">{POSITION_LABELS.at_depth}</option>
                          <option value="at_end">{POSITION_LABELS.at_end}</option>
                        </select>
                      </div>
                      <div>
                        <label className="label">匹配模式</label>
                        <select
                          className="select"
                          value={editingEntry.matchMode ?? 'both'}
                          onChange={(e) =>
                            setEditingEntry({
                              ...editingEntry,
                              matchMode: e.target.value as NonNullable<LoreEntry['matchMode']>,
                            })
                          }
                        >
                          <option value="keyword">{MATCH_MODE_LABELS.keyword}（仅关键词/正则）</option>
                          <option value="semantic">{MATCH_MODE_LABELS.semantic}（需先生成语义索引）</option>
                          <option value="both">{MATCH_MODE_LABELS.both}</option>
                        </select>
                        <p className="text-xs text-tavern-text-muted mt-1">
                          {editingEntry.matchMode === 'semantic'
                            ? '仅通过语义相似度触发：不依赖关键词，但需要先生成索引并启用「设置 → 语义触发」。'
                            : editingEntry.matchMode === 'both'
                              ? '关键词命中或语义相似（“猫娘”可触发含“猫咪”的条目）均可触发。'
                              : '仅按关键词/正则匹配触发。'}
                        </p>
                      </div>
                      {editingEntry.position === 'at_depth' && (
                        <div>
                          <label className="label">注入深度（0 = 最新消息前）</label>
                          <input
                            type="number"
                            min={0}
                            className="input"
                            value={editingEntry.depth ?? 0}
                            onChange={(e) =>
                              setEditingEntry({
                                ...editingEntry,
                                depth: Math.max(0, Number(e.target.value) || 0),
                              })
                            }
                          />
                        </div>
                      )}
                      <div>
                        <label className="label">顺序</label>
                        <input
                          type="number"
                          className="input"
                          value={editingEntry.order}
                          onChange={(e) =>
                            setEditingEntry({
                              ...editingEntry,
                              order: Number(e.target.value) || 0,
                            })
                          }
                        />
                      </div>
                      <div className="col-span-2">
                        <label className="label">触发概率：{editingEntry.probability}%</label>
                        <input
                          type="range"
                          min={0}
                          max={100}
                          value={editingEntry.probability}
                          onChange={(e) =>
                            setEditingEntry({
                              ...editingEntry,
                              probability: Number(e.target.value),
                            })
                          }
                          className="w-full accent-tavern-accent"
                        />
                      </div>
                      <div className="col-span-2 flex items-center gap-2">
                        <span className="text-sm text-tavern-text-soft">启用此条目</span>
                        <Toggle
                          checked={editingEntry.enabled}
                          onChange={(v) => setEditingEntry({ ...editingEntry, enabled: v })}
                        />
                      </div>
                    </div>
                  </div>
                )}
              </>
            )}
          </div>
        </div>
      )}

      {/* 删除世界书确认 */}
      <ConfirmDialog
        open={!!deleteId}
        onClose={() => setDeleteId(null)}
        onConfirm={handleDelete}
        title="删除世界书"
        message="确定要删除这本世界书吗？所有条目都将被删除。此操作不可撤销。"
        confirmText="删除"
        danger
      />

      {/* 删除条目确认 */}
      <ConfirmDialog
        open={!!deleteEntryId}
        onClose={() => setDeleteEntryId(null)}
        onConfirm={handleDeleteEntry}
        title="删除条目"
        message="确定要删除这个条目吗？此操作不可撤销。"
        confirmText="删除"
        danger
      />
    </div>
  )
}

import { useEffect, useRef, useState } from 'react'
import { nanoid } from 'nanoid'
import { Modal } from '../components/common/Modal'
import { EmptyState } from '../components/common/EmptyState'
import { ConfirmDialog } from '../components/common/ConfirmDialog'
import { cn } from '../lib/utils'
import { UserCircle, Plus, Trash2, Pencil, Check, Star } from 'lucide-react'
import type { Persona } from '../../shared/types'
import { useSettingsStore } from '../store/useSettingsStore'
import { usePersonaStore } from '../store/usePersonaStore'

export function PersonasPage() {
  const { settings, updateSettings } = useSettingsStore()
  const { personas, loadPersonas: storeLoadPersonas, savePersona, deletePersona: storeDeletePersona } = usePersonaStore()
  const [editing, setEditing] = useState<Persona | null>(null)
  const [deleteId, setDeleteId] = useState<string | null>(null)
  const [toast, setToast] = useState<string | null>(null)
  const toastTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null)

  const showToast = (msg: string) => {
    setToast(msg)
    if (toastTimerRef.current) clearTimeout(toastTimerRef.current)
    toastTimerRef.current = setTimeout(() => setToast(null), 3000)
  }

  // 默认身份置顶显示
  const sortedPersonas = [...personas].sort((a, b) => {
    const aDefault = settings.defaultPersonaId === a.id ? 1 : 0
    const bDefault = settings.defaultPersonaId === b.id ? 1 : 0
    return bDefault - aDefault
  })

  const loadPersonasAndInit = async () => {
    await storeLoadPersonas()
    const list = usePersonaStore.getState().personas
    // 首次使用：自动创建默认身份
    if (list.length === 0) {
      const defaultPersona: Persona = {
        id: nanoid(),
        name: settings.userName || '用户',
        description: settings.userDescription || '',
        persona: settings.userPersona || '',
        avatar: '',
        createdAt: Date.now(),
        updatedAt: Date.now(),
      }
      await savePersona(defaultPersona)
      updateSettings({ activePersonaId: defaultPersona.id })
    } else {
      // 如果没有激活的身份，激活第一个
      if (!settings.activePersonaId && list.length > 0) {
        activatePersona(list[0])
      }
    }
  }

  useEffect(() => {
    loadPersonasAndInit()
  }, [])

  const activatePersona = (p: Persona) => {
    updateSettings({
      activePersonaId: p.id,
      userName: p.name,
      userDescription: p.description,
      userPersona: p.persona,
    })
  }

  const handleNew = () => {
    setEditing({
      id: nanoid(),
      name: '新身份',
      description: '',
      persona: '',
      avatar: '',
      createdAt: Date.now(),
      updatedAt: Date.now(),
    })
  }

  const handleSave = async () => {
    if (!editing) return
    await savePersona(editing)
    setEditing(null)
    // 如果是当前激活的身份，同步更新 settings
    if (settings.activePersonaId === editing.id) {
      activatePersona(editing)
    }
  }

  const handleAvatarSelect = async () => {
    const path = await window.api.file.selectImage()
    if (path) {
      const base64 = await window.api.file.readImageAsBase64(path)
      setEditing(prev => prev ? { ...prev, avatar: base64 } : null)
    }
  }

  const handleDelete = async () => {
    if (!deleteId) return
    await storeDeletePersona(deleteId)
    // 如果删除的是当前激活身份，切换到第一个
    if (settings.activePersonaId === deleteId) {
      const remaining = usePersonaStore.getState().personas
      if (remaining.length > 0) {
        activatePersona(remaining[0])
      } else {
        updateSettings({ activePersonaId: null, userName: '用户', userDescription: '', userPersona: '' })
      }
    }
    // 如果删除的是默认身份，清除
    if (settings.defaultPersonaId === deleteId) {
      updateSettings({ defaultPersonaId: null })
    }
    setDeleteId(null)
  }

  // 切换默认身份（星标）：可设置也可取消
  const handleToggleDefault = (p: Persona) => {
    const isDefault = settings.defaultPersonaId === p.id
    updateSettings({ defaultPersonaId: isDefault ? null : p.id })
    showToast(isDefault
      ? `已取消「${p.name}」的默认身份`
      : `已将「${p.name}」设为默认身份，新建对话将默认使用`)
  }

  return (
    <div className="flex-1 flex flex-col overflow-hidden">
      <header className="flex items-center justify-between px-4 h-14 border-b border-tavern-border-soft bg-tavern-bg-soft shrink-0">
        <h1 className="font-display text-lg font-bold">用户身份</h1>
        <button onClick={handleNew} className="btn-primary">
          <Plus className="w-4 h-4" />
          新建身份
        </button>
      </header>

      <div className="flex-1 overflow-y-auto p-4">
        {personas.length === 0 ? (
          <EmptyState
            icon={<UserCircle className="w-8 h-8" />}
            title="暂无用户身份"
            description="创建多个身份，在不同场景下切换你的角色设定"
          />
        ) : (
          <div className="max-w-3xl mx-auto grid grid-cols-1 sm:grid-cols-2 gap-3">
            {sortedPersonas.map((p) => {
              const isActive = settings.activePersonaId === p.id
              return (
                <div
                  key={p.id}
                  className={cn(
                    'card p-4 cursor-pointer transition-all',
                    isActive ? 'border-tavern-accent ring-1 ring-tavern-accent/30' : 'hover:border-tavern-accent/50'
                  )}
                  onClick={() => activatePersona(p)}
                >
                  <div className="flex items-start gap-3">
                    {/* 头像 */}
                    <div className="w-14 h-14 rounded-full bg-tavern-bg-hover flex items-center justify-center shrink-0 overflow-hidden">
                      {p.avatar ? (
                        <img src={p.avatar} alt="" className="w-full h-full object-cover" />
                      ) : (
                        <UserCircle className="w-9 h-9 text-tavern-text-muted" />
                      )}
                    </div>

                    {/* 信息 */}
                    <div className="flex-1 min-w-0">
                      <div className="flex items-center gap-2">
                        <span className="font-medium text-tavern-text truncate">{p.name}</span>
                        {isActive && (
                          <span className="flex items-center gap-0.5 px-1.5 py-0.5 rounded text-xs bg-tavern-accent-soft text-tavern-accent shrink-0">
                            <Check className="w-3 h-3" />
                            当前
                          </span>
                        )}
                        {settings.defaultPersonaId === p.id && (
                          <span className="flex items-center gap-0.5 px-1.5 py-0.5 rounded text-xs bg-tavern-warning/15 text-tavern-warning shrink-0">
                            <Star className="w-3 h-3" />
                            默认
                          </span>
                        )}
                      </div>
                      {p.description && (
                        <p className="text-xs text-tavern-text-muted mt-1 line-clamp-2">{p.description}</p>
                      )}
                      {p.persona && (
                        <p className="text-xs text-tavern-text-muted mt-0.5">性格：{p.persona}</p>
                      )}
                    </div>

                    {/* 操作 */}
                    <div className="flex gap-1 shrink-0">
                      <button
                        onClick={(e) => {
                          e.stopPropagation()
                          handleToggleDefault(p)
                        }}
                        className={cn(
                          'p-1.5 rounded text-xs transition-colors',
                          settings.defaultPersonaId === p.id
                            ? 'text-tavern-warning bg-tavern-warning/15'
                            : 'text-tavern-text-muted hover:text-tavern-warning hover:bg-tavern-bg-hover'
                        )}
                        title={settings.defaultPersonaId === p.id ? '取消默认身份（新对话将不再默认使用）' : '设为默认身份（新建对话时默认使用）'}
                      >
                        <Star className="w-3.5 h-3.5" />
                      </button>
                      <button
                        onClick={(e) => { e.stopPropagation(); setEditing({ ...p }) }}
                        className="p-1.5 rounded text-tavern-text-muted hover:text-tavern-text hover:bg-tavern-bg-hover"
                      >
                        <Pencil className="w-3.5 h-3.5" />
                      </button>
                      <button
                        onClick={(e) => { e.stopPropagation(); setDeleteId(p.id) }}
                        className="p-1.5 rounded text-tavern-text-muted hover:text-tavern-danger hover:bg-tavern-bg-hover"
                      >
                        <Trash2 className="w-3.5 h-3.5" />
                      </button>
                    </div>
                  </div>
                </div>
              )
            })}
          </div>
        )}
      </div>

      {/* 编辑 Modal */}
      <Modal open={!!editing} onClose={() => setEditing(null)} title="编辑身份" width="lg">
        {editing && (
          <div className="space-y-4">
            {/* 头像 */}
            <div className="flex justify-center">
              <div
                className="w-20 h-20 rounded-full overflow-hidden bg-tavern-bg-hover border-2 border-tavern-border cursor-pointer relative group"
                onClick={handleAvatarSelect}
              >
                {editing.avatar ? (
                  <img src={editing.avatar} alt="" className="w-full h-full object-cover" />
                ) : (
                  <div className="w-full h-full flex items-center justify-center text-tavern-text-muted">
                    <UserCircle className="w-10 h-10" />
                  </div>
                )}
                <div className="absolute inset-0 bg-black/50 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center rounded-full">
                  <span className="text-xs text-white">更换头像</span>
                </div>
              </div>
            </div>
            <div>
              <label className="label">名称（{'{{user}}'} 替换值）</label>
              <input
                type="text"
                className="input"
                value={editing.name}
                onChange={(e) => setEditing({ ...editing, name: e.target.value })}
                placeholder="你的名字"
              />
              <p className="text-xs text-tavern-text-muted mt-1">在角色卡和预设中，{'{{user}}'} 会被替换为此名字</p>
            </div>
            <div>
              <label className="label">描述</label>
              <textarea
                className="textarea"
                rows={3}
                value={editing.description}
                onChange={(e) => setEditing({ ...editing, description: e.target.value })}
                placeholder="描述你的身份、背景等，AI 会了解这些信息"
              />
            </div>
            <div>
              <label className="label">性格</label>
              <textarea
                className="textarea"
                rows={2}
                value={editing.persona}
                onChange={(e) => setEditing({ ...editing, persona: e.target.value })}
                placeholder="你的性格特征，如：友善、好奇、内向等"
              />
            </div>
            <div className="flex justify-end gap-2">
              <button onClick={() => setEditing(null)} className="btn-secondary">取消</button>
              <button onClick={handleSave} className="btn-primary">保存</button>
            </div>
          </div>
        )}
      </Modal>

      <ConfirmDialog
        open={!!deleteId}
        onClose={() => setDeleteId(null)}
        onConfirm={handleDelete}
        title="删除身份"
        message="确定要删除这个用户身份吗？"
        confirmText="删除"
        danger
      />

      {/* 操作反馈提示 */}
      {toast && (
        <div className="fixed top-4 left-1/2 -translate-x-1/2 z-50 px-4 py-2.5 rounded-lg bg-tavern-bg-soft border border-tavern-border shadow-xl text-sm text-tavern-text animate-in fade-in slide-in-from-top-2">
          {toast}
        </div>
      )}
    </div>
  )
}

import { nanoid } from 'nanoid'
import type { GroupChat, GroupMessage, Character } from '../../shared/types'
import { useSettingsStore } from './useSettingsStore'
import { useCharacterStore } from './useCharacterStore'
import { lorebookCache } from '../utils/lorebook'
import type { BudgetLoreItem } from '../utils/lorebook'
import { estimateTokens } from '../utils/tokenCounter'
import { countChars } from '../utils/charCounter'
import { isLocalProvider } from '../utils/defaults'
import { replaceVariables } from '../utils/variables'
import { resolveEffectiveTemplate } from '../utils/chatTemplates'
import { applyRegexRules as applyRegexRulesEngine, truncateAtStop, collectStopStrings, findStopIndex } from '../utils/regex'
import { logError, logInfo, logWarn } from '../lib/logger'
import { STREAM_THROTTLE_MS, SEMANTIC_SCAN_MAX_TOKENS, STREAM_IDLE_TIMEOUT_MS } from './chatConstants'
import { friendlyError, semanticCacheGet, semanticCacheSet } from './chatUtils'
import type { GroupChatState, GroupStoreGet, GroupStoreSet } from './groupChatTypes'

// ====================== 流式状态管理（模块级） ======================

interface ActiveStream {
  requestId: string
  msgId: string
  accumulated: string
  flushTimer: ReturnType<typeof setTimeout> | null
  unbindChunk: () => void
  unbindDone: () => void
  unbindError: () => void
  timeoutHandle: ReturnType<typeof setTimeout> | null
}

let activeStream: ActiveStream | null = null

/** 读取当前活动流（stopStreaming 等需要读取） */
export function getActiveStream(): ActiveStream | null {
  return activeStream
}

/** 群聊上下文溢出压缩：待执行任务（buildGroupContext 标记，流式完成后消费） */
interface PendingGroupCompression {
  groupId: string
  sessionId: string
  droppedText: string
  droppedStartTs: number
  droppedEndTs: number
}

let pendingGroupCompression: PendingGroupCompression | null = null

/** 供 buildGroupContext 标记压缩任务（上下文溢出时） */
export function markPendingGroupCompression(pc: PendingGroupCompression): void {
  pendingGroupCompression = pc
}

/** 轮询定时器 handle，用于切换/删除群聊时清理 */
let pollingTimer: ReturnType<typeof setTimeout> | null = null

export function cleanupActiveStream() {
  if (!activeStream) return
  clearTimeout(activeStream.flushTimer!)
  clearTimeout(activeStream.timeoutHandle!)
  activeStream.unbindChunk()
  activeStream.unbindDone()
  activeStream.unbindError()
  activeStream = null
}

/** 清理轮询定时器 */
export function clearPollingTimer() {
  if (pollingTimer !== null) {
    clearTimeout(pollingTimer)
    pollingTimer = null
  }
}

/** 对文本应用正则规则（与单聊 applyRegex 逻辑一致：output 走 text + markdown 两阶段） */
function applyRegexRules(text: string, rules: import('../../shared/types').RegexRule[]): string {
  if (!text || rules.length === 0) return text
  const scoped = rules as import('../../shared/types').RegexRule[]
  let result = applyRegexRulesEngine(text, scoped, 'output', 'text').text
  result = applyRegexRulesEngine(result, scoped, 'output', 'markdown').text
  return result
}

async function flushStream(set: GroupStoreSet) {
  if (!activeStream) return
  const { msgId, accumulated } = activeStream
  activeStream.flushTimer = null
  set((s: GroupChatState) => ({
    messages: s.messages.map((m: GroupMessage) =>
      m.id === msgId ? { ...m, content: accumulated } : m,
    ),
    streamingContent: accumulated,
  }))
}

/**
 * 群聊语义触发（向量 RAG）预取：发言前异步检索语义命中的世界书条目。
 * 与单聊路径共用主进程 semanticSearch，失败静默降级为纯关键词触发。
 */
async function fetchGroupSemanticLoreHits(get: GroupStoreGet, set: GroupStoreSet, group: GroupChat, charName: string): Promise<void> {
  const settings = useSettingsStore.getState().settings
  const st = settings.semanticTrigger
  const clear = () => {
    if (get()._semanticLoreHits.length > 0) set({ _semanticLoreHits: [] })
  }
  if (!st?.enabled || !st.baseUrl?.trim() || !st.model?.trim()) return clear()

  // 群聊级 + 角色绑定世界书
  const charStore = useCharacterStore.getState()
  const allLorebookIds = new Set<string>(group.lorebookIds)
  group.memberIds.forEach((mid) => {
    const c = charStore.characters.find((ch) => ch.id === mid)
    if (c?.boundLorebookIds) c.boundLorebookIds.forEach((id) => allLorebookIds.add(id))
  })
  const lorebookIds = [...allLorebookIds]
  if (lorebookIds.length === 0) return clear()

  const scanDepth = lorebookIds
    .map(id => lorebookCache.get(id)?.scanDepth)
    .filter((d): d is number => typeof d === 'number' && d > 0)
    .reduce((max, d) => Math.max(max, d), 10)
  // 语义扫描范围：按 token 预算自适应（上限 4000 token，下限 scanDepth 条）
  const activeModel = useSettingsStore.getState().getActiveProfile()?.model || settings.activeModel
  const scanText = (() => {
    const msgs = get().messages
    const picked: string[] = []
    let tokens = 0
    for (let i = msgs.length - 1; i >= 0 && picked.length < scanDepth; i--) {
      const m = msgs[i] as GroupMessage
      const content = m.characterId === '__user__'
        ? m.content
        : `【${charStore.characters.find((ch) => ch.id === m.characterId)?.name || '未知角色'}】${m.content}`
      if (!m.content) continue
      tokens += estimateTokens(content, activeModel)
      if (picked.length > 0 && tokens > SEMANTIC_SCAN_MAX_TOKENS) break
      picked.unshift(content)
    }
    return picked.join(' ')
  })()
  if (!scanText.trim()) return clear()

  // 缓存：同一轮对话扫描文本不变时复用命中（省嵌入 API 调用）
  const cacheKey = `glore|${lorebookIds.join(',')}|${scanText}|${st.model}`
  const cached = semanticCacheGet<BudgetLoreItem[]>(cacheKey)
  if (cached) {
    set({ _semanticLoreHits: cached })
    return
  }

  try {
    const hits = await window.api.embedding.semanticSearch({
      scanText,
      lorebookIds,
      config: {
        provider: st.provider,
        baseUrl: st.baseUrl,
        model: st.model,
        apiKey: st.apiKey ?? '',
      },
      threshold: st.threshold,
      maxResults: st.maxResults,
    })
    const items: BudgetLoreItem[] = (hits ?? []).map((h) => ({
      content: replaceVariables(h.content, settings.userName, charName || '角色'),
      order: h.order,
      position: h.position,
      depth: h.depth,
    }))
    set({ _semanticLoreHits: items })
    semanticCacheSet(cacheKey, items)
    if (items.length > 0) {
      logInfo('fetchGroupSemanticLoreHits', `语义命中 ${items.length} 条世界书条目`)
    }
  } catch (e) {
    logError('fetchGroupSemanticLoreHits', e)
    clear()
  }
}

/**
 * 群聊记忆事实语义检索预取（P0-2）：失败回退全量注入。
 */
async function fetchGroupSemanticFacts(get: GroupStoreGet, set: GroupStoreSet): Promise<void> {
  const settings = useSettingsStore.getState().settings
  const st = settings.semanticTrigger
  const clear = () => {
    if (get()._semanticFactsHits.length > 0) set({ _semanticFactsHits: [] })
  }
  if (!st?.enabled || !st.baseUrl?.trim() || !st.model?.trim()) return clear()

  const { sessions, currentSessionId } = get()
  const session = sessions.find((s) => s.id === currentSessionId)
  if (!session?.memoryEnabled || !session.memoryFacts?.length) return clear()
  const vectors = session.factsVectors
  if (!vectors || vectors.length !== session.memoryFacts.length) return clear()

  const query = get().messages.slice(-20).map((m) => m.content).join(' ')
  if (!query.trim()) return clear()

  // 缓存：同一轮对话查询不变时复用（省嵌入 API 调用）
  const cacheKey = `gfacts|${session.id}|${query}|${st.model}`
  const cached = semanticCacheGet<string[]>(cacheKey)
  if (cached) {
    set({ _semanticFactsHits: cached })
    return
  }

  try {
    const hits = await window.api.embedding.searchFacts({
      query,
      facts: session.memoryFacts,
      vectors,
      config: {
        provider: st.provider,
        baseUrl: st.baseUrl,
        model: st.model,
        apiKey: st.apiKey ?? '',
      },
      threshold: st.threshold,
      maxResults: st.maxResults ?? 3,
    })
    set({ _semanticFactsHits: hits ?? [] })
    semanticCacheSet(cacheKey, hits ?? [])
  } catch {
    clear()
  }
}

/**
 * 群聊记忆事实向量化（P0-2）
 */
export async function vectorizeGroupSessionFacts(groupId: string, sessionId: string, facts: string[]): Promise<void> {
  if (!facts?.length) return
  const st = useSettingsStore.getState().settings.semanticTrigger
  if (!st?.enabled || !st.baseUrl?.trim() || !st.model?.trim()) return
  try {
    const vectors = await window.api.embedding.embedFacts({
      provider: st.provider,
      baseUrl: st.baseUrl,
      model: st.model,
      apiKey: st.apiKey ?? '',
    }, facts)
    if (vectors.length === facts.length) {
      await window.api.group.updateSession(groupId, sessionId, { factsVectors: vectors })
    }
  } catch { /* 忽略 */ }
}

/**
 * 群聊上下文溢出压缩（P0-1）：异步压缩被裁剪的早期群聊内容，存群聊会话。
 */
async function compressGroupDroppedHistory(
  get: GroupStoreGet,
  set: GroupStoreSet,
  group: GroupChat,
  pending: PendingGroupCompression,
): Promise<void> {
  if (!pending.sessionId || !pending.droppedText) return
  const settings = useSettingsStore.getState().settings
  const profile = useSettingsStore.getState().getActiveProfile()
  if (!profile || (!profile.apiKey && !isLocalProvider(profile.provider))) return

  const requestId = `group-compress-${Date.now()}`
  let result = ''
  let finished = false

  const unbindChunk = window.api.ai.onChunk((data) => {
    if (data.requestId !== requestId) return
    result += data.text
  })
  const unbindDone = window.api.ai.onDone((doneId) => {
    if (doneId !== requestId) return
    cleanup()
    finished = true
    const summary = result.replace(/<thought>[\s\S]*?<\/thought>/gi, '').trim()
    if (summary) {
      window.api.group.updateSession(group.id, pending.sessionId, {
        compressedSummary: summary,
        compressedRange: { startTs: pending.droppedStartTs, endTs: pending.droppedEndTs },
      }).then(async () => {
        const sessions = await window.api.group.listSessions(group.id)
        set({ sessions })
      }).catch(() => { /* 忽略 */ })
    }
  })
  const unbindError = window.api.ai.onError((data) => {
    if (data.requestId !== requestId) return
    cleanup()
    finished = true
  })
  const cleanup = () => {
    unbindChunk(); unbindDone(); unbindError()
  }

  window.api.ai.chat({
    requestId,
    messages: [
      {
        role: 'system',
        content: `你是一个对话摘要助手。以下是群聊「${group.name}」的早期内容，即将被上下文裁剪。请压缩为 3-5 句中文摘要，必须保留：各角色身份与姓名、地点、目标、关键事件、未解决的问题、重要的约定。只输出摘要文本，不要任何解释。`,
      },
      { role: 'user', content: pending.droppedText.slice(0, 20000) },
    ],
    provider: profile.provider,
    apiKey: profile.apiKey,
    baseUrl: profile.baseUrl,
    model: settings.activeModel || profile.model,
    temperature: 0.3,
    topP: 0.9,
    maxTokens: 600,
    frequencyPenalty: 0,
    presencePenalty: 0,
    stream: true,
  }).catch(() => {
    cleanup()
    if (!finished) logWarn('compressGroupDroppedHistory', '压缩请求失败')
  })
}

export async function streamGroupAI(
  set: GroupStoreSet,
  get: GroupStoreGet,
  group: GroupChat,
  sessionId: string,
  speaker: Character,
  round: number,
  onComplete: () => void,
) {
  const settingsStore = useSettingsStore.getState()
  const profile = settingsStore.getActiveProfile()
  if (!profile) return

  // 加载预设（群聊预设优先，回退到角色绑定预设）
  let preset = null
  if (group.presetId) {
    const allPresets = await window.api.preset.list()
    preset = allPresets.find(p => p.id === group.presetId) ?? null
  } else if (speaker.boundPresetId) {
    const allPresets = await window.api.preset.list()
    preset = allPresets.find(p => p.id === speaker.boundPresetId) ?? null
  }

  // 加载正则规则
  let regexRules: import('../../shared/types').RegexRule[] = []
  try {
    regexRules = await window.api.regex.list()
  } catch { /* 忽略 */ }

  // 预加载角色绑定的世界书
  if (speaker.boundLorebookIds && speaker.boundLorebookIds.length > 0) {
    await get().ensureLorebooksLoaded(speaker.boundLorebookIds)
  }

  // 语义触发预取（向量 RAG）：失败静默降级为纯关键词
  await fetchGroupSemanticLoreHits(get, set, group, speaker.name)
  // 记忆事实语义检索预取（P0-2）：失败回退全量注入
  await fetchGroupSemanticFacts(get, set)

  const context = get().buildGroupContext(speaker.id, preset)

  if (context.length === 0) return

  const requestId = nanoid()
  const msgId = nanoid()

  // 等待中的占位消息
  const placeholder: GroupMessage = {
    id: msgId,
    groupId: group.id,
    characterId: speaker.id,
    content: '',
    images: [],
    timestamp: Date.now(),
    round,
  }
  set((s: GroupChatState) => ({
    messages: [...s.messages, placeholder],
    isStreaming: true,
    currentStreamingCharId: speaker.id,
    streamingContent: '',
    error: null,
  }))

  // 停止字符串（output 正则规则）：流式命中后截断 + 提前终止，省 token
  const stopStrings = collectStopStrings(regexRules)

  // 绑定流式事件
  const unbindChunk = window.api.ai.onChunk((data: { requestId: string; text: string }) => {
    if (data.requestId !== requestId || !activeStream || activeStream.requestId !== requestId) return
    activeStream.accumulated += data.text
    // 停止字符串：命中后截断并提前终止（主进程取消后发 ai:done，走正常收尾）
    if (stopStrings.length > 0) {
      const idx = findStopIndex(activeStream.accumulated, stopStrings)
      if (idx !== -1) {
        activeStream.accumulated = activeStream.accumulated.slice(0, idx).trimEnd()
        if (activeStream.flushTimer) {
          clearTimeout(activeStream.flushTimer)
          activeStream.flushTimer = null
        }
        flushStream(set)
        window.api.ai.cancelChat(requestId).catch(() => {})
        return
      }
    }
    if (activeStream.flushTimer === null) {
      activeStream.flushTimer = setTimeout(() => flushStream(set), STREAM_THROTTLE_MS)
    }
    // 空闲超时续期：收到 chunk 即重置 60s 计时（卡死时更快恢复）
    if (activeStream.timeoutHandle) clearTimeout(activeStream.timeoutHandle)
    activeStream.timeoutHandle = setTimeout(() => {
      const partialContent = activeStream?.accumulated ?? ''
      cleanupActiveStream()
      window.api.ai.cancelChat(requestId).catch((e) => logError('GroupChatStore:cancelChat', e))
      const clean = partialContent.replace(/<thought>[\s\S]*?<\/thought>/gi, '').trim()
      if (clean) {
        set((s: GroupChatState) => ({
          messages: s.messages.map((m: GroupMessage) =>
            m.id === msgId ? { ...m, content: clean + '\n\n⚠️ 请求超时' } : m,
          ),
          isStreaming: false, currentStreamingCharId: null, streamingContent: '', error: '请求超时',
        }))
        window.api.group.saveMessage(group.id, sessionId, {
          id: msgId, groupId: group.id, characterId: speaker.id,
          content: clean + '\n\n⚠️ 请求超时', images: [], timestamp: Date.now(), round,
        }).catch((e) => logError('GroupChatStore:saveMessage', e))
      } else {
        set((s: GroupChatState) => ({
          messages: s.messages.filter((m: GroupMessage) => m.id !== msgId),
          isStreaming: false, currentStreamingCharId: null, streamingContent: '', error: '请求超时',
        }))
      }
    }, STREAM_IDLE_TIMEOUT_MS)
  })

  const unbindDone = window.api.ai.onDone((doneId: string) => {
    if (doneId !== requestId || !activeStream || activeStream.requestId !== requestId) return

    if (activeStream.flushTimer !== null) {
      clearTimeout(activeStream.flushTimer)
      activeStream.flushTimer = null
    }

    const finalContent = activeStream.accumulated

    cleanupActiveStream()

    // 剥离 thought
    const clean = finalContent.replace(/<thought>[\s\S]*?<\/thought>/gi, '').trim()

    // 应用正则规则 + 停止字符串截断
    const processed = regexRules.length > 0
      ? truncateAtStop(applyRegexRules(clean, regexRules), collectStopStrings(regexRules)).text
      : clean

    // 更新消息
    set((s: GroupChatState) => ({
      messages: s.messages.map((m: GroupMessage) =>
        m.id === msgId ? { ...m, content: processed || '(无回复)' } : m,
      ),
      isStreaming: false,
      currentStreamingCharId: null,
      streamingContent: '',
    }))

    // 持久化
    window.api.group.saveMessage(group.id, sessionId, {
      id: msgId,
      groupId: group.id,
      characterId: speaker.id,
      content: processed || '(无回复)',
      images: [],
      timestamp: Date.now(),
      round,
    })

    // 字符用量统计
    const model = useSettingsStore.getState().settings.activeModel || profile.model
    const outputChars = countChars(processed || '').total
    const usageInfo = { inputChars: 0, outputChars, totalChars: outputChars, model, timestamp: Date.now() }
    set((s: GroupChatState) => ({
      messages: s.messages.map((m: GroupMessage) => m.id === msgId ? { ...m, charUsage: usageInfo } : m),
    }))
    const sid = get().currentSessionId
    if (sid) {
      window.api.usage.record({
        timestamp: Date.now(), characterId: speaker.id, sessionId: sid, model,
        inputChars: 0, outputChars, totalChars: outputChars,
      }).catch((e) => logError('GroupChatStore:recordUsage', e))
    }

    // 上下文溢出压缩：本轮结束后异步执行
    if (pendingGroupCompression) {
      const pc = pendingGroupCompression
      pendingGroupCompression = null
      compressGroupDroppedHistory(get, set, group, pc).catch((e) => logError('GroupChatStore:compress', e))
    }

    onComplete()
  })

  const unbindError = window.api.ai.onError((data: { requestId: string; error: string }) => {
    if (data.requestId !== requestId) return

    if (activeStream?.flushTimer !== null) {
      clearTimeout(activeStream.flushTimer!)
    }
    // C-02 修复：先保存 accumulated 再 cleanup，否则 activeStream 已被置 null
    const accumulated = activeStream?.accumulated ?? ''
    cleanupActiveStream()

    const friendlyMsg = friendlyError(data.error)
    const errContent = accumulated
      ? accumulated + '\n\n⚠️ ' + friendlyMsg
      : '⚠️ ' + friendlyMsg

    set((s: GroupChatState) => ({
      messages: s.messages.map((m: GroupMessage) =>
        m.id === msgId ? { ...m, content: errContent } : m,
      ),
      isStreaming: false,
      currentStreamingCharId: null,
      streamingContent: '',
      error: data.error,
    }))

    window.api.group.saveMessage(group.id, sessionId, {
      id: msgId,
      groupId: group.id,
      characterId: speaker.id,
      content: errContent,
      images: [],
      timestamp: Date.now(),
      round,
    })
  })

  activeStream = {
    requestId,
    msgId,
    accumulated: '',
    flushTimer: null,
    unbindChunk,
    unbindDone,
    unbindError,
    timeoutHandle: setTimeout(() => {
      const partialContent = activeStream?.accumulated ?? ''
      cleanupActiveStream()
      window.api.ai.cancelChat(requestId).catch((e) => logError('GroupChatStore:cancelChat', e))
      const clean = partialContent.replace(/<thought>[\s\S]*?<\/thought>/gi, '').trim()
      if (clean) {
        // 有部分内容，保留并标记超时
        set((s: GroupChatState) => ({
          messages: s.messages.map((m: GroupMessage) =>
            m.id === msgId ? { ...m, content: clean + '\n\n⚠️ 请求超时' } : m,
          ),
          isStreaming: false, currentStreamingCharId: null, streamingContent: '', error: '请求超时',
        }))
        window.api.group.saveMessage(group.id, sessionId, {
          id: msgId, groupId: group.id, characterId: speaker.id,
          content: clean + '\n\n⚠️ 请求超时', images: [], timestamp: Date.now(), round,
        }).catch((e) => logError('GroupChatStore:saveMessage', e))
      } else {
        // 无内容，移除占位消息
        set((s: GroupChatState) => ({
          messages: s.messages.filter((m: GroupMessage) => m.id !== msgId),
          isStreaming: false, currentStreamingCharId: null, streamingContent: '', error: '请求超时',
        }))
      }
    }, STREAM_IDLE_TIMEOUT_MS),
  }

  // 发起 AI 请求
  try {
    const instructTemplate = resolveEffectiveTemplate(
      preset?.contextTemplate,
      profile.provider,
      profile.model,
      profile.useInstructTemplate,
    )
    await window.api.ai.chat({
      requestId,
      messages: context,
      provider: profile.provider,
      apiKey: profile.apiKey,
      baseUrl: profile.baseUrl,
      model: profile.model,
      temperature: preset?.temperature ?? 0.8,
      topP: preset?.topP ?? 0.95,
      maxTokens: preset?.maxTokens ?? 1024,
      frequencyPenalty: preset?.frequencyPenalty ?? 0,
      presencePenalty: preset?.presencePenalty ?? 0,
      stream: true,
      instructTemplate,
    })
  } catch (err) {
    cleanupActiveStream()
    set({
      isStreaming: false,
      currentStreamingCharId: null,
      streamingContent: '',
      error: err instanceof Error ? err.message : '请求失败',
    })
  }
}

